{"path": "/app/ars.R", "content": "## =============================================================================
##  ars.R -- Adaptive Rejection Sampling (Gilks & Wild, 1992)
##
##  Gilks, W. R. & Wild, P. (1992). Adaptive rejection sampling for Gibbs
##  sampling. Journal of the Royal Statistical Society, Series C (Applied
##  Statistics), 41(2), 337-348.
##
##  ARS samples from a distribution whose *log* density is concave, using an
##  adaptive upper hull built from tangents to the log density and a lower
##  squeezing hull built from the chords between the tangent points.
##
##  Layout of this file
##    1. Input validation helpers      (ars_validate_*)
##    2. Log-density evaluation        (ars_eval_logdensity, ars_is_log_concave)
##    3. Hull construction / sampling  (ars_init_hull, ars_update_hull,
##                                      ars_sample_hull, ars_hull_log_integral)
##    4. Main sampler                  (ars)
##    5. Sample summary / file output  (ars_summary, ars_write_samples)
##    6. Formal tests                  (test)
##
##  Style conventions
##    * every public object is prefixed with `ars_` (or is `ars` / `test`);
##    * every helper returns a value rather than modifying state in place,
##      except `ars_update_hull()` and `ars_do_sample()` which are documented
##      as mutating their environment argument in place;
##    * user-facing problems are signalled with `stop()` and a message starting
##      with "ars: " (or "ars_<helper>: " for the helpers).
## =============================================================================


## =============================================================================
## 1. Input validation
## =============================================================================

##' Convert a user supplied density into a vectorised log-density function.
##'
##' @param dfun Either (a) a function (or a function name given as a string) of
##'   one argument that must be vectorised in that argument -- e.g. `dnorm`,
##'   `dexp`, `"dgamma"`; or (b) a single expression / string written in terms
##'   of `x`, giving a possibly unnormalised density, e.g. `"exp(-x^2)"`.
##' @param log Logical; TRUE if `dfun` is already a log density.
##' @param ... Further fixed arguments passed to `dfun` (e.g. `sd = 2`).
##' @return A function of one numeric vector argument returning log density.
ars_make_logdensity <- function(dfun, log = FALSE, ...) {
  dots <- list(...)

  if (is.character(dfun)) {
    if (length(dfun) != 1L) {
      stop("ars: `dfun` must be a single function name or a single expression when given as a string.")
    }
    fn <- if (exists(dfun, mode = "function")) {
      get(dfun, mode = "function")
    } else {
      NULL
    }
    if (!is.null(fn)) {
      dfun <- fn
    } else {
      ## treat the string as an expression in `x`
      expr <- try(parse(text = dfun)[[1L]], silent = TRUE)
      if (inherits(expr, "try-error")) {
        stop("ars: `dfun` is neither the name of a known function nor a valid expression in `x`: ",
             dfun)
      }
      dfun <- function(x) eval(expr, list(x = x))
      if (log) {
        return(function(x) as.numeric(dfun(x)))
      }
      return(function(x) {
        v <- suppressWarnings(as.numeric(dfun(x)))
        log(v)
      })
    }
  }

  if (!is.function(dfun)) {
    stop("ars: `dfun` must be a function, a function name, or an expression in `x`; got ",
         class(dfun)[1L], ".")
  }

  forced <- function(x) {
    if (length(dots)) do.call(dfun, c(list(x), dots)) else dfun(x)
  }

  ## Test vectorisation on a small probe.  A density that silently returns a
  ## single value for a vector argument is not usable by ARS.
  if (log) {
    f <- function(x) .ars_safe_numeric(forced(x), x)
    probe <- f(c(-0.5, 0, 0.5))
    if (length(probe) != 3L) {
      stop("ars: `dfun` does not appear to be vectorised (it does not return one value per input).")
    }
    return(f)
  }

  ## When `dfun` is a "d"-style density we can get log dnorm() directly, which
  ## avoids underflow for far tail evaluations.  We only do this for functions
  ## that accept a `log` argument.
  has_log_arg <- "log" %in% names(formals(dfun))
  f <- function(x) {
    v <- if (has_log_arg) {
      .ars_safe_numeric(do.call(dfun, c(list(x, log = TRUE), dots)), x)
    } else {
      v <- .ars_safe_numeric(forced(x), x)
      log(v)
    }
    if (has_log_arg) v else v
  }
  probe <- f(c(-0.5, 0, 0.5))
  if (length(probe) != 3L) {
    stop("ars: `dfun` does not appear to be vectorised (it does not return one value per input).")
  }
  f
}

##' Coerce the output of a user density to a numeric vector of `length(x)`,
##' giving a clear error if that is impossible.
.ars_safe_numeric <- function(value, x) {
  value <- suppressWarnings(as.numeric(value))
  if (length(value) == 1L && length(x) > 1L) {
    value <- rep(value, length(x))
  }
  if (length(value) != length(x)) {
    stop("ars: the density function must be vectorised: it returned ", length(value),
         " value(s) for ", length(x), " input value(s).")
  }
  value
}

##' Validate the `x` argument (the support / starting points).
ars_validate_x <- function(x) {
  if (missing(x) || is.null(x) || length(x) == 0L) {
    stop("ars: `x` must supply at least one point in the support of the density.")
  }
  if (!is.numeric(x)) {
    stop("ars: `x` must be numeric; got ", class(x)[1L], ".")
  }
  if (anyNA(x) || any(is.nan(x))) {
    stop("ars: `x` must not contain NA or NaN.")
  }
  if (any(is.infinite(x))) {
    stop("ars: `x` must be finite (support bounds are supplied through `lower`/`upper`).")
  }
  if (anyDuplicated(x)) {
    x <- unique(x)
    warning("ars: duplicated values in `x` were removed.")
  }
  sort(x)
}

##' Validate the support bounds `lower` and `upper`.
ars_validate_bounds <- function(lower, upper, x) {
  if (!is.numeric(lower) || length(lower) != 1L || is.na(lower)) {
    stop("ars: `lower` must be a single number (-Inf allowed).")
  }
  if (!is.numeric(upper) || length(upper) != 1L || is.na(upper)) {
    stop("ars: `upper` must be a single number (Inf allowed).")
  }
  if (lower >= upper) {
    stop("ars: invalid domain: `lower` (", lower, ") must be strictly less than `upper` (", upper, ").")
  }
  if (any(x <= lower) || any(x >= upper)) {
    stop("ars: all values of `x` must lie strictly inside (", lower, ", ", upper, ").")
  }
  list(lower = lower, upper = upper)
}

##' Validate the number of samples to draw.
ars_validate_n <- function(n) {
  if (missing(n) || length(n) != 1L) {
    stop("ars: `n` must be a single number.")
  }
  if (!is.numeric(n) || is.na(n)) {
    stop("ars: `n` must be a single, non-missing number; got ", class(n)[1L], ".")
  }
  if (n < 0) {
    stop("ars: `n` must be non-negative; got ", n, ".")
  }
  if (is.infinite(n)) {
    stop("ars: `n` must be finite.")
  }
  if (n != round(n)) {
    stop("ars: `n` must be a whole number; got ", n, ".")
  }
  as.integer(n)
}

##' Validate the numerical control parameters supplied to `ars`.
ars_validate_control <- function(maxit, tol, max_width, min_width) {
  if (!is.numeric(maxit) || length(maxit) != 1L || is.na(maxit) || maxit < 1) {
    stop("ars: `maxit` must be a single positive number.")
  }
  if (!is.numeric(tol) || length(tol) != 1L || is.na(tol) || tol <= 0) {
    stop("ars: `tol` must be a single positive number.")
  }
  if (!is.numeric(max_width) || length(max_width) != 1L || is.na(max_width) || max_width <= 0) {
    stop("ars: `max_width` must be a single positive number.")
  }
  if (!is.numeric(min_width) || length(min_width) != 1L || is.na(min_width) || min_width <= 0) {
    stop("ars: `min_width` must be a single positive number.")
  }
  if (min_width >= max_width) {
    stop("ars: `min_width` must be smaller than `max_width`.")
  }
  list(maxit = as.integer(maxit), tol = tol, max_width = max_width, min_width = min_width)
}

##' Validate the output file argument.
ars_validate_file <- function(file) {
  if (is.null(file)) return(NULL)
  if (!is.character(file) || length(file) != 1L || is.na(file) || !nzchar(file)) {
    stop("ars: `file` must be NULL or a single non-empty file name.")
  }
  file
}


## =============================================================================
## 2. Log density evaluation and log-concavity checking
## =============================================================================

##' Evaluate the log density, mapping -Inf to NA so that it can be detected.
ars_eval_logdensity <- function(f, x) {
  v <- tryCatch(f(x), error = function(e) {
    stop("ars: the density function failed when evaluated at ", paste(format(x), collapse = ", "),
         ": ", conditionMessage(e))
  })
  v <- .ars_safe_numeric(v, x)
  v[is.nan(v)] <- NA_real_
  v
}

##' Check log-concavity *locally* by verifying that the slopes of the tangent
##' segments are non-increasing, i.e. that the secant slopes between successive
##' evaluation points `s_i = (h(x_{i+1}) - h(x_i)) / (x_{i+1} - x_i)` satisfy
##' `s_i >= s_{i+1}` (second difference of `h` is <= 0).
##'
##' This is the discrete analogue of Gilks & Wild's assumption (i) (log density
##' concave) and (ii) (h' continuous).  It is the check that is applied
##' repeatedly *during sampling*, after each new point has been added to the
##' hull, so any observed non-log-concavity aborts the sampler with an error.
##'
##' @param x Numeric vector of evaluation points (must be sorted, length >= 3).
##' @param h Log density at `x`.
##' @param tol Numerical tolerance for the slope comparison.
##' @return NULL invisibly; errors if concavity is violated.
ars_is_log_concave <- function(x, h, tol = 1e-8, context = "log density") {
  x <- as.numeric(x)
  h <- as.numeric(h)
  if (length(x) < 3L) return(invisible(TRUE))
  if (anyNA(h) || any(!is.finite(h))) {
    stop("ars: the ", context, " must be finite at every evaluation point used to build the hull.")
  }
  slopes <- diff(h) / diff(x)
  bad <- which(diff(slopes) > tol * pmax(1, abs(slopes[-1L]) + abs(slopes[-length(slopes)])))
  if (length(bad)) {
    i <- bad[1L]
    stop("ars: the ", context, " is not log-concave: the slopes of the log density increase ",
         "between x = ", format(x[i]), " and x = ", format(x[i + 2L]),
         " (slopes ", format(signif(slopes[i], 6)), " then ",
         format(signif(slopes[i + 1L], 6)), "). ",
         "Adaptive rejection sampling requires a log-concave density.")
  }
  invisible(TRUE)
}


## =============================================================================
## 3. Hull construction and sampling
## =============================================================================

##' Build the initial adaptive-hull state from the starting abscissae.
##'
##' The state is an environment (used so that the hull can grow cheaply during
##' sampling) with components
##'   h       -- log density at `x`
##'   hprime  -- derivative of the log density at `x`
##'   lower, upper -- support bounds (possibly infinite)
##'   z       -- breakpoints (length n+1); z[1] = lower, z[n+2] = upper
ars_init_hull <- function(f, x, lower, upper) {
  h <- ars_eval_logdensity(f, x)
  hp <- ars_logdensity_derivative(f, x)
  ars_is_log_concave(x, h, context = "log density at the initial points")

  state <- new.env(parent = emptyenv())
  state$f <- f
  state$lower <- lower
  state$upper <- upper
  state$x <- as.numeric(x)
  state$h <- h
  state$hprime <- hp
  state$n_added <- 0L
  state$z <- ars_hull_breakpoints(state$lower, state$upper, state$x, state$h, state$hprime)
  ars_check_hull(state)
  state
}

##' Numerical derivative of the log density (central differences).
ars_logdensity_derivative <- function(f, x) {
  h <- 1e-5 * pmax(1, abs(x))
  fplus <- ars_eval_logdensity(f, x + h)
  fminus <- ars_eval_logdensity(f, x - h)
  d <- (fplus - fminus) / (2 * h)
  bad <- !is.finite(d)
  if (any(bad)) {
    stop("ars: could not compute the derivative of the log density at x = ",
         paste(format(x[bad]), collapse = ", "),
         ". Check that the density is strictly positive and well behaved at these points.")
  }
  d
}

##' Breakpoints of the tangent (upper-hull) piecewise linear approximation.
##'
##' Intersection of the tangents at x_i and x_{i+1}:
##'   z_{i+1} = (h(x_{i+1}) - x_{i+1} h'(x_{i+1}) - h(x_i) + x_i h'(x_i)) /
##'             (h'(x_i) - h'(x_{i+1}))
ars_hull_breakpoints <- function(lower, upper, x, h, hprime) {
  k <- length(x)
  mid <- numeric(k - 1L)
  if (k > 1L) {
    for (i in seq_len(k - 1L)) {
      denom <- hprime[i] - hprime[i + 1L]
      if (abs(denom) < 1e-12) {
        mid[i] <- (x[i] + x[i + 1L]) / 2
      } else {
        mid[i] <- (h[i + 1L] - x[i + 1L] * hprime[i + 1L] - h[i] + x[i] * hprime[i]) / denom
      }
    }
  }
  z <- c(lower, mid, upper)
  z
}

##' Verify that the hull is a valid upper bound: breakpoints strictly
##' increasing, every tangent non-negative at its own interval, and (at finite
##' support bounds) the tangents pointing outwards.
ars_check_hull <- function(state) {
  z <- state$z
  x <- state$x
  if (any(diff(z) < 0)) {
    stop("ars: the tangent hull is not ordered in x. This indicates that the log density is ",
         "not concave (the tangent intersections are not increasing).")
  }
  n <- length(x)
  for (i in seq_len(n)) {
    left <- z[i]
    right <- z[i + 1L]
    if (right <= left) {
      stop("ars: empty hull interval around x = ", format(x[i]),
           "; the log density appears not to be concave (tangents cross in the wrong order).")
    }
    if (is.finite(left)) {
      v <- state$h[i] + (left - x[i]) * state$hprime[i]
      if (!is.finite(v) || v < -1e-8) {
        stop("ars: the tangent at x = ", format(x[i]), " is not a valid upper bound on the left. ",
             "This indicates that the log density is not concave (or that `lower` is inside the support).")
      }
    }
    if (is.finite(right)) {
      v <- state$h[i] + (right - x[i]) * state$hprime[i]
      if (!is.finite(v) || v < -1e-8) {
        stop("ars: the tangent at x = ", format(x[i]), " is not a valid upper bound on the right. ",
             "This indicates that the log density is not concave (or that `upper` is inside the support).")
      }
    }
  }
  invisible(TRUE)
}

##' Log of the normalising constant of one piece of the upper hull, i.e.
##' log int_{left}^{right} exp(h(x_i) + (t - x_i) h'(x_i)) dt.
##' Works for infinite limits using the analytic limits of the integral.
ars_piece_log_integral <- function(left, right, xi, hi, hpi) {
  ## upper hull on the piece is  U(t) = hi + (t - xi) * hpi
  ## so  log U(t) = A + B t  with  A = hi - xi*hpi,  B = hpi
  A <- hi - xi * hpi
  B <- hpi
  if (abs(B) < 1e-14) {
    ## flat: integral = exp(A) * (right - left)
    if (!is.finite(left) || !is.finite(right)) {
      return(Inf)
    }
    return(A + log(right - left))
  }
  ## int_l^r exp(A + B t) dt = [exp(A + B t)/B]_l^r = exp(A)/B * (exp(B r) - exp(B l))
  ## Compute in a numerically stable way.
  hi_l <- if (is.finite(left)) A + B * left else -Inf
  hi_r <- if (is.finite(right)) A + B * right else -Inf
  if (B > 0) {
    ## B>0: term at r dominates (r could be +Inf)
    if (is.infinite(hi_r) || is.na(hi_r)) return(Inf)
    if (!is.finite(hi_r) && hi_r > 0) return(Inf)
    ## log( (exp(hi_r) - exp(hi_l))/B ) = hi_r - log(B) + log1p(-exp(hi_l - hi_r))
    if (hi_l > hi_r) {
      ## B > 0 but left dominates: fall back to the "left" branch
      return(ars_piece_log_integral_side(left, right, A, B))
    }
    return(hi_r - log(B) + log1p(-exp(hi_l - hi_r)))
  } else {
    ## B<0: term at l dominates
    if (!is.finite(hi_l)) return(Inf)
    ## log( (exp(hi_r) - exp(hi_l)) / B ) ; B<0 -> divide by -|B|
    ## = log( (exp(hi_l) - exp(hi_r)) / |B| )
    return(hi_l - log(-B) + log1p(-exp(hi_r - hi_l)))
  }
}

##' Fallback for the piecewise integral when the dominant endpoint is not the
##' one suggested by the sign of the slope (happens for degenerate pieces).
ars_piece_log_integral_side <- function(left, right, A, B) {
  hi_l <- if (is.finite(left)) A + B * left else -Inf
  hi_r <- if (is.finite(right)) A + B * right else -Inf
  m <- max(hi_l, hi_r)
  if (!is.finite(m)) return(Inf)
  tot <- exp(hi_l - m) + exp(hi_r - m)   # rough stable estimate
  m + log(tot) - log(abs(B))
}

##' Sample `m` values from the piecewise-exponential upper hull already
##' normalised, i.e. a vector of interval indices is returned.
ars_sample_hull_interval <- function(state, m) {
  n <- length(state$x)
  li <- vapply(seq_len(n), function(i) {
    ars_piece_log_integral(state$z[i], state$z[i + 1L], state$x[i], state$h[i], state$hprime[i])
  }, numeric(1L))
  if (any(is.na(li))) {
    stop("ars: the upper hull has non-integrable pieces; the density may not be log-concave ",
         "or its support may be wrong. Check `lower`/`upper`.")
  }
  maxli <- max(li)
  if (!is.finite(maxli)) {
    stop("ars: the normalising constant of the upper hull is infinite. ",
         "The log density is either not log-concave or growing on the supplied support.")
  }
  w <- exp(li - maxli)
  ## guard against all-zero weights
  if (sum(w) == 0 || !is.finite(sum(w))) {
    stop("ars: could not normalise the upper hull (numerical failure).")
  }
  prob <- w / sum(w)
  cum <- cumsum(prob)
  cum[n] <- 1
  u <- stats::runif(m)
  idx <- findInterval(u, cum) + 1L
  idx[idx > n] <- n
  idx
}

##' Draw `m` values from the piecewise exponential upper hull.
ars_sample_hull <- function(state, m) {
  n <- length(state$x)
  idx <- ars_sample_hull_interval(state, m)
  left <- state$z[idx]
  right <- state$z[idx + 1L]
  xi <- state$x[idx]
  hi <- state$h[idx]
  hpi <- state$hprime[idx]
  u <- stats::runif(m)
  out <- numeric(m)

  flat <- abs(hpi) < 1e-14
  ## flat pieces: uniform on the piece (must be finite)
  if (any(flat)) {
    lf <- left[flat]; rf <- right[flat]
    if (any(!is.finite(lf)) || any(!is.finite(rf))) {
      stop("ars: a flat piece of the log density has infinite support, which is not integrable.")
    }
    out[flat] <- lf + u[flat] * (rf - lf)
  }
  ## sloped pieces
  s <- which(!flat)
  if (length(s)) {
    l <- left[s]; r <- right[s]; sl <- hpi[s]; x0 <- xi[s]; h0 <- hi[s]
    ## inverse CDF on [l, r];  F(t) = (exp(s t) - exp(s l)) / (exp(s r) - exp(s l))
    log_p_l <- s * (l - x0)   # = h(l) - h(x0) ignoring base
    log_p_r <- s * (r - x0)
    ## handle infinite endpoints via the analytic inverse
    for (j in seq_along(s)) {
      ll <- log_p_l[j]; rr <- log_p_r[j]; uj <- u[s][j]; slj <- sl[j]
      if (!is.finite(ll) && !is.finite(rr)) {
        stop("ars: internal error: hull piece infinite at both ends.")
      }
      if (is.finite(ll) && is.finite(rr)) {
        ## standard case
        lo <- min(ll, rr); hi2 <- max(ll, rr)
        val <- log1p(uj * expm1(hi2 - lo)) + lo   # log( exp(lo) + u (exp(hi) - exp(lo)) )
        t <- x0[j] + val / slj
      } else if (!is.finite(ll)) {
        ## left = -Inf: exp(s(l - x0)) -> 0 if s*(l-x0) -> -Inf
        ## F(t) = exp(s(t-x0) - log_p_r )
        t <- x0[j] + (log(uj) + rr) / slj
      } else {
        ## right = +Inf: F(t) = 1 - exp(s(t - x0) - log_p_l)
        f <- 1 - exp(slj * (t <- x0[j]) - x0[j] * 0)
        ## use: 1 - u = exp(s(t-x0) - log_p_l)
        t <- x0[j] + (log1p(-uj) + ll) / slj
      }
      out[s][j] <- t
    }
  }
  if (any(!is.finite(out))) {
    stop("ars: generated a non-finite sample from the upper hull.")
  }
  ## keep samples strictly inside the support
  eps <- 1e-12 * pmax(1, abs(out))
  out <- pmin(pmax(out, if (is.finite(state$lower)) state$lower + eps else -Inf),
              if (is.finite(state$upper)) state$upper - eps else Inf)
  out
}

##' Add a new abscissa to the hull (mutates `state`).
ars_update_hull <- function(state, xnew) {
  if (any(!is.finite(xnew))) {
    stop("ars: cannot add a non-finite point to the hull.")
  }
  if (any(xnew <= state$lower) || any(xnew >= state$upper)) {
    stop("ars: cannot add a point outside the support ", "(", state$lower, ", ", state$upper, ").")
  }
  for (x in xnew) {
    if (any(abs(state$x - x) < 1e-12 * pmax(1, abs(x)))) next  # already present
    hnew <- ars_eval_logdensity(state$f, x)
    if (length(hnew) != 1L) hnew <- hnew[1L]
    if (is.na(hnew) || !is.finite(hnew)) {
      stop("ars: the log density is not finite at the new hull point x = ", format(x),
           ". The density must be strictly positive on its support.")
    }
    hpnew <- ars_logdensity_derivative(state$f, x)
    ## insert keeping x sorted
    pos <- findInterval(x, state$x) + 1L
    state$x <- append(state$x, x, after = pos - 1L)
    state$h <- append(state$h, hnew, after = pos - 1L)
    state$hprime <- append(state$hprime, hpnew, after = pos - 1L)
    state$n_added <- state$n_added + 1L
  }
  ## log-concavity check on the enlarged set (this is the check performed
  ## *during* sampling)
  ars_is_log_concave(state$x, state$h, context = "log density (after adding a hull point)")
  state$z <- ars_hull_breakpoints(state$lower, state$upper, state$x, state$h, state$hprime)
  ars_check_hull(state)
  invisible(state)
}

##' Log of the lower (squeezing) hull at `x`, given the current abscissae.
##' Outside [min(x), max(x)] the squeezing hull is -Inf (no squeeze available).
ars_squeeze_log <- function(state, x) {
  xs <- state$x
  res <- rep(-Inf, length(x))
  k <- length(xs)
  if (k < 2L) return(res)
  idx <- findInterval(x, xs)
  inside <- idx >= 1L & idx < k
  if (any(inside)) {
    i <- idx[inside]
    xi <- x[inside]
    sl <- (state$h[i + 1L] - state$h[i]) / (xs[i + 1L] - xs[i])
    res[inside] <- state$h[i] + (xi - xs[i]) * sl
  }
  res
}

##' Log of the upper (tangent) hull at `x`.
ars_upper_log <- function(state, x) {
  xs <- state$x
  idx <- findInterval(x, state$z)
  idx <- pmin(pmax(idx, 1L), length(xs))
  state$h[idx] + (x - xs[idx]) * state$hprime[idx]
}


## =============================================================================
## 4. Main sampler
## =============================================================================

##' Adaptive rejection sampler for log-concave densities (Gilks & Wild, 1992).
##'
##' @param n Number of samples required (non-negative whole number).
##' @param dfun Density function: a vectorised function of one argument (e.g.
##'   `dnorm`, `dexp`, or a user function), the name of such a function, or a
##'   string expression in `x` giving a possibly unnormalised density.
##' @param x Optional numeric vector of starting abscissae (strictly inside the
##'   support).  If missing, sensible defaults are derived from `lower`/`upper`.
##' @param lower,upper Support bounds; may be infinite (log density must decay
##'   there).  Defaults to `-Inf`, `Inf`.
##' @param log Logical; is `dfun` already a log density?
##' @param ... Further arguments passed to `dfun` (e.g. `sd`, `rate`).
##' @param file Optional file name; if given the samples are written there
##'   (one per line) as a side effect.
##' @param maxit Maximum number of hull points that may be added.
##' @param tol Tolerance used in the log-concavity check.
##' @param max_width,min_width Control the automatic choice of starting points.
##' @param verbose Print a short progress/summary report.
##' @return A numeric vector of length `n` (class `"ars"`) with attributes
##'   `n_added`, `n_rejected`, `n_squeezed`, `hull_x`, `call`.
ars <- function(n, dfun, x = NULL, lower = -Inf, upper = Inf, log = FALSE, ...,
                file = NULL, maxit = 500L, tol = 1e-8,
                max_width = 1, min_width = 1e-3, verbose = FALSE) {
  call <- match.call()

  ## ---- input validation --------------------------------------------------
  n <- ars_validate_n(n)
  ctl <- ars_validate_control(maxit, tol, max_width, min_width)
  file <- ars_validate_file(file)
  if (!is.logical(log) || length(log) != 1L || is.na(log)) {
    stop("ars: `log` must be TRUE or FALSE.")
  }
  if (!is.logical(verbose) || length(verbose) != 1L || is.na(verbose)) {
    stop("ars: `verbose` must be TRUE or FALSE.")
  }
  f <- ars_make_logdensity(dfun, log = log, ...)

  if (n == 0L) {
    out <- numeric(0)
    class(out) <- "ars"
    attributes(out) <- c(attributes(out), list(n_added = 0L, n_rejected = 0L,
                                               n_squeezed = 0L, hull_x = numeric(0)))
    return(out)
  }

  if (is.null(x)) {
    x <- ars_default_x(f, lower, upper, max_width = ctl$max_width,
                       min_width = ctl$min_width)
  }
  if (length(x) < 2L) {
    ## need at least two abscissae to build a hull; add a neighbour
    x <- c(x, x + max(ctl$max_width, 1e-3))
  }
  x <- ars_validate_x(x)
  bnd <- ars_validate_bounds(lower, upper, x)
  lower <- bnd$lower; upper <- bnd$upper

  ## ---- initial hull (also checks log-concavity) -------------------------
  state <- ars_init_hull(f, x, lower, upper)

  ## ---- main adaptive rejection loop -------------------------------------
  out <- numeric(n)
  filled <- 0L
  n_rejected <- 0L
  n_squeezed <- 0L
  attempts <- 0L
  max_attempts <- 100L * n + 1000L

  while (filled < n) {
    attempts <- attempts + 1L
    if (attempts > max_attempts) {
      stop("ars: giving up after ", attempts, " rejection-sampling attempts. ",
           "The supplied density may not be log-concave.")
    }
    m <- n - filled
    cand <- ars_sample_hull(state, m)

    ## log-concavity / validity checks on the sampled candidates: the log
    ## density must be defined and finite, and must lie below the tangent hull.
    log_target <- ars_eval_logdensity(f, cand)
    if (any(is.na(log_target) | !is.finite(log_target))) {
      bad <- cand[is.na(log_target) | !is.finite(log_target)]
      stop("ars: the log density is not finite at candidate point(s) x = ",
           paste(format(signif(bad, 6)), collapse = ", "),
           ". The density must be strictly positive on its support (and `lower`/`upper` ",
           "must bound the support correctly).")
    }
    log_upper <- ars_upper_log(state, cand)
    if (any(log_target > log_upper + 1e-6 * pmax(1, abs(log_upper)))) {
      stop("ars: the log density exceeded its tangent upper hull; the density is not log-concave.")
    }
    log_squeeze <- ars_squeeze_log(state, cand)
    u <- log(stats::runif(m))

    ## squeezed acceptance
    squeezed <- is.finite(log_squeeze) & u <= log_squeeze - log_upper
    n_squeezed <- n_squeezed + sum(squeezed)

    ## full evaluation for the rest
    need <- !squeezed
    accepted <- squeezed
    if (any(need)) {
      log_accept <- u[need] <= log_target[need] - log_upper[need]
      acc_idx <- which(need)[log_accept]
      accepted[acc_idx] <- TRUE
      ## rejected candidates become new hull points (adaptive step)
      rej <- which(need)[!log_accept]
      if (length(rej)) {
        n_rejected <- n_rejected + length(rej)
        if (state$n_added + length(rej) > ctl$maxit) {
          stop("ars: the maximum number of hull points (", ctl$maxit,
               ") was reached. The density may not be log-concave, or the support ",
               "bounds may be too wide.")
        }
        ars_update_hull(state, cand[rej])
      }
    }

    ## store accepted values
    take <- which(accepted)
    if (length(take)) {
      k <- min(length(take), n - filled)
      out[filled + seq_len(k)] <- cand[take[seq_len(k)]]
      filled <- filled + k
    }
  }

  attributes(out) <- c(attributes(out), list(
    n_added = state$n_added,
    n_rejected = n_rejected,
    n_squeezed = n_squeezed,
    hull_x = state$x,
    call = call
  ))
  class(out) <- "ars"

  if (!is.null(file)) {
    ars_write_samples(out, file)
  }
  if (verbose) {
    cat(sprintf(
      "ars: drew %d samples; %d hull points added, %d rejections, %d squeeze acceptances.\n",
      n, state$n_added, n_rejected, n_squeezed))
  }
  out
}

##' Choose reasonable starting abscissae when the user does not supply `x`.
##' We walk outwards from 0 (or from the middle of a finite support) in steps
##' of `max_width` (shrinking towards `min_width`) until the log density has
##' decayed enough that a hull on that region is integrable.
ars_default_x <- function(f, lower, upper, max_width = 1, min_width = 1e-3) {
  start <- if (is.finite(lower) && is.finite(upper)) {
    (lower + upper) / 2
  } else if (is.finite(lower)) {
    lower + max_width
  } else if (is.finite(upper)) {
    upper - max_width
  } else {
    0
  }
  xs <- start
  h0 <- ars_eval_logdensity(f, start)
  if (!is.finite(h0)) {
    stop("ars: the log density is not finite at the default starting point x = ",
         format(start), ". Please supply `x` (strictly inside the support), and check ",
         "`lower`/`upper`.")
  }
  ## initial neighbourhood around the starting point
  xs <- sort(unique(c(start - max_width / 2, start, start + max_width / 2)))
  xs <- xs[xs > lower & xs < upper]
  h <- ars_eval_logdensity(f, xs)
  ok <- is.finite(h)
  xs <- xs[ok]; h <- h[ok]
  if (length(xs) < 2L) {
    stop("ars: could not find two usable starting points. Please supply `x`.")
  }
  ## expand outwards while the density is still appreciable
  for (side in c(-1, 1)) {
    step <- max_width
    while (step >= min_width) {
      cand <- if (side < 0) min(xs) - step else max(xs) + step
      if (cand <= lower || cand >= upper) break
      hc <- ars_eval_logdensity(f, cand)
      if (!is.finite(hc) || hc < max(h) - 30) break
      xs <- sort(c(xs, cand)); h <- ars_eval_logdensity(f, xs)
      step <- max_width
    }
  }
  if (length(xs) < 2L) {
    stop("ars: could not find two usable starting points. Please supply `x`.")
  }
  xs
}


## =============================================================================
## 5. Summaries and file output
## =============================================================================

##' Summary statistics of an `ars` sample.
ars_summary <- function(samples) {
  s <- as.numeric(samples)
  list(n = length(s),
       mean = mean(s),
       sd = if (length(s) > 1L) stats::sd(s) else NA_real_,
       min = min(s), max = max(s),
       median = stats::median(s),
       n_added = attr(samples, "n_added"),
       n_rejected = attr(samples, "n_rejected"))
}

print.ars <- function(x, ...) {
  s <- ars_summary(x)
  cat("Adaptive rejection sample\n")
  cat(sprintf("  n        : %d\n", s$n))
  cat(sprintf("  mean     : %.6f\n", s$mean))
  cat(sprintf("  sd       : %.6f\n", s$sd))
  cat(sprintf("  range    : [%.6f, %.6f]\n", s$min, s$max))
  cat(sprintf("  hull pts : %d added, %d rejections\n", s$n_added, s$n_rejected))
  invisible(x)
}

##' Write samples to a plain text file, one value per line.
ars_write_samples <- function(samples, file) {
  file <- ars_validate_file(file)
  con <- tryCatch(file(file, "w"), error = function(e) {
    stop("ars: cannot open '", file, "' for writing: ", conditionMessage(e))
  })
  on.exit(close(con), add = TRUE)
  writeLines(format(as.numeric(samples), digits = 15, trim = TRUE), con)
  invisible(file)
}


## =============================================================================
## 6. Formal testing
## =============================================================================

##' Tiny test-harness helpers: record and print "NAME: PASS" / "NAME: FAIL".
.ars_test_state <- new.env(parent = emptyenv())
.ars_test_state$results <- list()

.ars_report <- function(name, passed, details = NULL, stats = NULL) {
  status <- if (isTRUE(passed)) "PASS" else "FAIL"
  cat(sprintf("%s: %s\n", name, status))
  if (!is.null(details)) cat(sprintf("    %s\n", details))
  if (!is.null(stats)) {
    for (nm in names(stats)) {
      cat(sprintf("    %s = %s\n", nm, format(signif(stats[[nm]], 6))))
    }
  }
  .ars_test_state$results[[name]] <- isTRUE(passed)
  invisible(isTRUE(passed))
}

##' Run an expression, returning TRUE/FALSE and the error message.
.ars_expect_error <- function(expr) {
  tryCatch({
    force(expr)
    list(ok = FALSE, msg = "no error was raised")
  }, error = function(e) list(ok = TRUE, msg = conditionMessage(e)))
}

##' Compare sample mean / sd with the theoretical values using a z-test on the
##' mean and a chi-square style test on the variance.  Because the samples are
##' genuinely random this uses tolerances that are wide enough to keep the false
##' rejection rate small (about 4 standard errors for the mean) while still
##' catching a sampler that returns the wrong distribution.
.ars_check_moments <- function(x, true_mean, true_sd, label, n_sd = 4, rel_var_tol = 0.1) {
  n <- length(x)
  m <- mean(x)
  s <- stats::sd(x)
  se <- true_sd / sqrt(n)
  z <- (m - true_mean) / se
  mean_ok <- abs(z) <= n_sd
  sd_ok <- abs(s / true_sd - 1) <= rel_var_tol
  passed <- mean_ok && sd_ok
  .ars_report(label, passed,
    details = sprintf("mean %.4f vs true %.4f (z = %.2f, |z| <= %.1f); sd %.4f vs true %.4f",
                      m, true_mean, z, n_sd, s, true_sd),
    stats = c(sample_mean = m, sample_sd = s, true_mean = true_mean, true_sd = true_sd))
  passed
}

##' Kolmogorov-Smirnov goodness of fit against the exact CDF, at level 0.001.
.ars_check_ks <- function(x, cdf, label, tolerance = 0.001) {
  test <- suppressWarnings(stats::ks.test(x, cdf))
  passed <- test$p.value > tolerance
  .ars_report(label, passed,
    details = sprintf("KS statistic %.5f, p-value %.4f (> %.3f)", test$statistic, test$p.value, tolerance),
    stats = c(ks_statistic = as.numeric(test$statistic), ks_p_value = test$p.value))
  passed
}

##' The formal test suite.  Prints one "NAME: PASS"/"NAME: FAIL" line per test
##' plus informative statistics, and returns (invisibly) a named logical vector.
test <- function(write_files = TRUE, n = 20000L, seed = 20240517L) {
  .ars_test_state$results <- list()
  cat("================================================================\n")
  cat(" Testing the adaptive rejection sampler (Gilks & Wild, 1992)\n")
  cat("================================================================\n\n")

  set.seed(seed)

  ## ---------------------------------------------------------------- helpers
  cat("-- Auxiliary functions -----------------------------------------\n")

  ## log-concavity detector: concave (normal) vs not concave (Cauchy)
  r <- .ars_expect_error(
    ars_is_log_concave(c(-2, -1, 0, 1, 2), dcauchy(c(-2, -1, 0, 1, 2), log = TRUE)))
  .ars_report("log_concavity_detects_cauchy", r$ok, details = r$msg)

  ok_concave <- isTRUE(tryCatch({
    ars_is_log_concave(c(-2, -1, 0, 1, 2), dnorm(c(-2, -1, 0, 1, 2), log = TRUE)); TRUE
  }, error = function(e) FALSE))
  .ars_report("log_concavity_accepts_normal", ok_concave,
              details = "concave log density must not be flagged")

  ## log-concavity detector on an exponential
  ok_exp <- isTRUE(tryCatch({
    ars_is_log_concave(c(0.5, 1, 2, 4, 8), dexp(c(0.5, 1, 2, 4, 8), log = TRUE)); TRUE
  }, error = function(e) FALSE))
  .ars_report("log_concavity_accepts_exponential", ok_exp)

  ## log-concavity detector catches a bimodal (non log-concave) mixture
  bimodal <- function(x) log(0.5 * dnorm(x, -3, 1) + 0.5 * dnorm(x, 3, 1))
  r <- .ars_expect_error(ars_is_log_concave(seq(-5, 5, by = 1), bimodal(seq(-5, 5, by = 1))))
  .ars_report("log_concavity_detects_bimodal", r$ok, details = r$msg)

  ## expression input is converted to a log density
  f <- ars_make_logdensity("exp(-x^2/2)")
  val <- f(0)
  .ars_report("expression_input_parsed", isTRUE(all.equal(val, 0)),
              details = sprintf("log density at 0 = %.6f (expected 0)", val))
  vec <- f(c(-1, 0, 1))
  .ars_report("expression_input_vectorised", length(vec) == 3L,
              details = sprintf("returned %d values for 3 inputs", length(vec)))

  ## dnorm given as a function and as a name agree
  f1 <- ars_make_logdensity(dnorm)
  f2 <- ars_make_logdensity("dnorm")
  agree <- isTRUE(all.equal(f1(c(-1, 0, 2)), f2(c(-1, 0, 2))))
  .ars_report("density_from_function_and_name", agree,
              details = "dnorm() and \"dnorm\" give identical log densities")

  ## non-vectorised density is rejected
  r <- .ars_expect_error(ars_make_logdensity(function(x) sum(x)))
  .ars_report("non_vectorised_density_rejected", r$ok, details = r$msg)

  ## ------------------------------------------------------------ validation
  cat("\n-- Input validation --------------------------------------------\n")

  r <- .ars_expect_error(ars(-5, dnorm, x = c(-1, 1)))
  .ars_report("reject_negative_n", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(2.5, dnorm, x = c(-1, 1)))
  .ars_report("reject_fractional_n", r$ok, details = r$msg)

  r <- .ars_expect_error(ars("10", dnorm, x = c(-1, 1)))
  .ars_report("reject_non_numeric_n", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 1), lower = 2, upper = 1))
  .ars_report("reject_invalid_domain", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 5), lower = -Inf, upper = 2))
  .ars_report("reject_x_outside_support", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(0, 0, 0)))
  .ars_report("reject_degenerate_x", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, NA)))
  .ars_report("reject_NA_in_x", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, "not_a_function_or_expression((("))
  .ars_report("reject_bad_density_input", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 1), file = 42))
  .ars_report("reject_bad_file_argument", r$ok, details = r$msg)

  ## n = 0 is legal and returns an empty vector
  z <- tryCatch(ars(0, dnorm), error = function(e) e)
  .ars_report("accept_zero_n", is.numeric(z) && length(z) == 0L,
              details = "ars(0, dnorm) returns a length-0 numeric vector")

  ## --------------------------------------------------- non log-concave run
  cat("\n-- Non log-concave densities -----------------------------------\n")

  r <- .ars_expect_error(ars(100, dcauchy, x = c(-1, 0.5, 1)))
  .ars_report("reject_cauchy_density", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(100, bimodal, x = c(-4, -2, 2, 4)))
  .ars_report("reject_bimodal_density", r$ok, details = r$msg)

  ## density that is negative somewhere inside the supplied support
  r <- .ars_expect_error(ars(100, function(x) dnorm(x, 0, 1) - 0.2,
                             x = c(-1, 0, 1), lower = -10, upper = 10))
  .ars_report("reject_density_negative_on_support", r$ok, details = r$msg)

  ## ------------------------------------------------ correctness: normal
  cat(sprintf("\n-- Normal(0, 1) : %d samples --------------------------------\n", n))
  s_norm <- ars(n, dnorm, x = c(-1.5, 0, 1.5))
  .ars_check_moments(s_norm, 0, 1, "normal_mean_sd")
  .ars_check_ks(s_norm, pnorm, "normal_ks_test")
  .ars_report("normal_samples_in_support", all(is.finite(s_norm)) && length(s_norm) == n,
              details = sprintf("all %d samples finite", n))
  .ars_report("normal_hull_adaptive", attr(s_norm, "n_added") > 0L,
              details = sprintf("%d hull points added during sampling", attr(s_norm, "n_added")))

  ## comparison with the truth beyond the first two moments: quantiles
  qs <- stats::quantile(s_norm, c(0.01, 0.25, 0.5, 0.75, 0.99))
  truth <- stats::qnorm(c(0.01, 0.25, 0.5, 0.75, 0.99))
  qok <- all(abs(qs - truth) < 0.05)
  .ars_report("normal_quantiles", qok,
              details = paste(sprintf("q%d: %.4f vs %.4f", c(1, 25, 50, 75, 99), qs, truth),
                              collapse = "; "))

  ## not uniform: a uniform sample would have sd ~ 1/sqrt(12) on the observed range
  spread_ok <- abs(stats::sd(s_norm) / 1 - 1) < 0.05
  .ars_report("normal_not_uniform_shape", spread_ok,
              details = sprintf("sample sd %.4f is consistent with N(0,1), not with a uniform draw",
                                stats::sd(s_norm)))

  ## --------------------------------------------- correctness: exponential
  cat(sprintf("\n-- Exponential(rate = 2) on (0, Inf) : %d samples ------------\n", n))
  s_exp <- ars(n, dexp, x = c(0.2, 0.7, 1.5), lower = 0, rate = 2)
  .ars_check_moments(s_exp, 1 / 2, 1 / 2, "exponential_mean_sd")
  .ars_check_ks(s_exp, function(p) pexp(p, rate = 2), "exponential_ks_test")
  .ars_report("exponential_positive_support", all(s_exp > 0),
              details = sprintf("min sample %.5f > 0", min(s_exp)))

  ## ---------------------------------------- correctness: truncated normal
  cat(sprintf("\n-- Truncated N(0,1) on (-1, 2) : %d samples -----------------\n", n))
  a <- -1; b <- 2
  Z <- pnorm(b) - pnorm(a)
  tn_mean <- (dnorm(a) - dnorm(b)) / Z
  tn_var <- 1 + (a * dnorm(a) - b * dnorm(b)) / Z - tn_mean^2
  s_trunc <- ars(n, dnorm, x = c(-0.5, 0, 0.5), lower = a, upper = b)
  .ars_check_moments(s_trunc, tn_mean, sqrt(tn_var), "truncated_normal_mean_sd")
  .ars_check_ks(s_trunc, function(p) (pnorm(p) - pnorm(a)) / Z, "truncated_normal_ks_test")
  .ars_report("truncated_normal_in_bounds", all(s_trunc > a & s_trunc < b),
              details = sprintf("range [%.4f, %.4f] inside (-1, 2)", min(s_trunc), max(s_trunc)))

  ## ----------------------------------- correctness: unnormalised / gamma
  cat(sprintf("\n-- Unnormalised density exp(-x^2/2) : %d samples -------------\n", n))
  s_expr <- ars(n, "exp(-x^2/2)", x = c(-1, 0, 1))
  .ars_check_moments(s_expr, 0, 1, "unnormalised_expression_mean_sd")

  cat(sprintf("\n-- Gamma(3, rate = 1) log-concave : %d samples ---------------\n", n))
  s_gam <- ars(n, dgamma, x = c(1, 2, 3), lower = 0, shape = 3, rate = 1)
  .ars_check_moments(s_gam, 3, sqrt(3), "gamma_mean_sd")
  .ars_check_ks(s_gam, function(p) pgamma(p, shape = 3, rate = 1), "gamma_ks_test")

  ## ------------------------------------------------------ file output
  cat("\n-- Sample files ------------------------------------------------\n")
  if (write_files) {
    ok_norm <- isTRUE(tryCatch({
      ars_write_samples(s_norm, "/app/normal_samples.txt"); TRUE
    }, error = function(e) FALSE))
    ok_exp <- isTRUE(tryCatch({
      ars_write_samples(s_exp, "/app/exponential_samples.txt"); TRUE
    }, error = function(e) FALSE))
    chk_norm <- ok_norm && file.exists("/app/normal_samples.txt") &&
      length(readLines("/app/normal_samples.txt")) == length(s_norm)
    chk_exp <- ok_exp && file.exists("/app/exponential_samples.txt") &&
      length(readLines("/app/exponential_samples.txt")) == length(s_exp)
    .ars_report("write_normal_samples_file", chk_norm,
                details = "/app/normal_samples.txt")
    .ars_report("write_exponential_samples_file", chk_exp,
                details = "/app/exponential_samples.txt")

    ## file argument inside ars()
    tmpfile <- tempfile()
    invisible(ars(1000, dnorm, x = c(-1, 1), file = tmpfile))
    .ars_report("ars_file_argument_writes", file.exists(tmpfile) && length(readLines(tmpfile)) == 1000,
                details = sprintf("1000 lines written to a temporary file"))
    unlink(tmpfile)
  }

  ## ------------------------------------------------------------ summary
  res <- unlist(.ars_test_state$results)
  cat("\n================================================================\n")
  cat(sprintf(" %d of %d tests passed\n", sum(res), length(res)))
  if (all(res)) {
    cat(" ALL TESTS PASSED\n")
  } else {
    cat(" FAILED TESTS:", paste(names(res)[!res], collapse = ", "), "\n")
  }
  cat("================================================================\n")
  invisible(res)
}


## =============================================================================
## Run the tests when this file is executed directly:
##     Rscript ars.R
## =============================================================================
if (!interactive() && sys.nframe() == 0L) {
  test()
}
"}

{"path": "ars.R", "content": "## =============================================================================
##  ars.R -- Adaptive Rejection Sampling (Gilks & Wild, 1992)
##
##  Gilks, W. R. & Wild, P. (1992). Adaptive rejection sampling for Gibbs
##  sampling. Journal of the Royal Statistical Society, Series C (Applied
##  Statistics), 41(2), 337-348.
##
##  ARS samples from a distribution whose *log* density is concave, using an
##  adaptive upper hull built from tangents to the log density and a lower
##  (squeezing) hull built from the chords between the tangent points.
##
##  Layout of this file
##    1. Input validation helpers      (ars_validate_*)
##    2. Log-density evaluation        (ars_eval_logdensity, ars_is_log_concave)
##    3. Hull construction / sampling  (ars_init_hull, ars_update_hull,
##                                      ars_sample_hull, ars_squeeze_log, ...)
##    4. Main sampler                  (ars)
##    5. Summary / file output         (ars_summary, ars_write_samples)
##    6. Formal tests                  (test)
##
##  Style conventions
##    * every public object is prefixed with `ars_` (or is `ars` / `test`);
##    * helpers return values rather than side effects, except
##      `ars_update_hull()` which is documented as mutating its `state`
##      environment in place (so the hull can grow cheaply);
##    * user-facing problems are signalled with `stop()` and a message that
##      starts with "ars: ".
## =============================================================================


## =============================================================================
## 1. Input validation
## =============================================================================

##' Coerce the output of a user density to a numeric vector of `length(x)`,
##' giving a clear error if that is impossible.
.ars_safe_numeric <- function(value, x) {
  value <- suppressWarnings(as.numeric(value))
  if (length(value) == 1L && length(x) > 1L) {
    value <- rep(value, length(x))
  }
  if (length(value) != length(x)) {
    stop("ars: the density function must be vectorised: it returned ", length(value),
         " value(s) for ", length(x), " input value(s).")
  }
  value
}

##' Convert a user supplied density into a vectorised log-density function.
##'
##' @param dfun Either (a) a function, or the name of a function given as a
##'   string, of one argument that must be vectorised in that argument -- e.g.
##'   `dnorm`, `dexp`, `"dgamma"`; or (b) a single expression / string written
##'   in terms of `x`, giving a possibly unnormalised density, e.g.
##'   `"exp(-x^2)"`.
##' @param log Logical; TRUE if `dfun` already returns a log density.
##' @param ... Further fixed arguments passed to `dfun` (e.g. `sd = 2`).
##' @return A function of one numeric vector argument returning log density.
ars_make_logdensity <- function(dfun, log = FALSE, ...) {
  dots <- list(...)

  if (is.character(dfun)) {
    if (length(dfun) != 1L) {
      stop("ars: `dfun` must be a single function name or a single expression when given as a string.")
    }
    is_fn_name <- isTRUE(tryCatch(exists(dfun, mode = "function"), error = function(e) FALSE))
    if (is_fn_name) {
      dfun <- get(dfun, mode = "function")
    } else {
      ## treat the string as an expression in `x`
      expr <- try(parse(text = dfun), silent = TRUE)
      if (inherits(expr, "try-error") || length(expr) != 1L) {
        stop("ars: `dfun` is neither the name of a known function nor a valid expression in `x`: ",
             dfun)
      }
      expr <- expr[[1L]]
      raw_fun <- function(x) eval(expr, list(x = x))
      return(.ars_build_logdensity(raw_fun, log = log, dots = list()))
    }
  }

  if (!is.function(dfun)) {
    stop("ars: `dfun` must be a function, a function name, or an expression in `x`; got ",
         class(dfun)[1L], ".")
  }
  .ars_build_logdensity(dfun, log = log, dots = dots)
}

##' Wrap `dfun` (+ its extra arguments) into a checked vectorised log density.
.ars_build_logdensity <- function(dfun, log, dots) {
  ## When `dfun` is a "d"-style density we can ask for log = TRUE directly,
  ## which avoids underflow for far tail evaluations.
  has_log_arg <- isTRUE("log" %in% names(formals(dfun)))

  f <- function(x) {
    v <- if (has_log_arg) {
      do.call(dfun, c(list(x, log = TRUE), dots))
    } else {
      v <- do.call(dfun, c(list(x), dots))
      log(v)
    }
    .ars_safe_numeric(v, x)
  }

  if (log && !has_log_arg) {
    ## dfun already returns logs but has no `log` argument
    f <- function(x) {
      v <- do.call(dfun, c(list(x), dots))
      if (isTRUE(log)) v <- log(v)
      .ars_safe_numeric(v, x)
    }
  } else if (log && has_log_arg) {
    f <- function(x) .ars_safe_numeric(do.call(dfun, c(list(x, log = TRUE), dots)), x)
  }

  ## Test vectorisation on a small probe.  A density that silently returns a
  ## single value for a vector argument is not usable by ARS.
  probe <- suppressWarnings(try(f(c(-0.5, 0, 0.5)), silent = TRUE))
  if (inherits(probe, "try-error") || length(probe) != 3L) {
    stop("ars: `dfun` does not appear to be vectorised (it does not return one value per ",
         "input value). ARS needs a vectorised density such as dnorm().")
  }

  attr(f, "ars_has_log_arg") <- has_log_arg
  f
}

##' Validate the `x` argument (starting abscissae / support interior points).
ars_validate_x <- function(x) {
  if (is.null(x) || length(x) == 0L) {
    stop("ars: `x` must supply at least one point in the support of the density.")
  }
  if (!is.numeric(x)) {
    stop("ars: `x` must be numeric; got ", class(x)[1L], ".")
  }
  if (anyNA(x) || any(is.nan(x))) {
    stop("ars: `x` must not contain NA or NaN.")
  }
  if (any(is.infinite(x))) {
    stop("ars: `x` must be finite (support bounds are supplied through `lower`/`upper`).")
  }
  if (anyDuplicated(x)) {
    x <- unique(x)
    warning("ars: duplicated values in `x` were removed.")
  }
  sort(x)
}

##' Validate the support bounds `lower` and `upper`.
ars_validate_bounds <- function(lower, upper, x) {
  if (!is.numeric(lower) || length(lower) != 1L || is.na(lower)) {
    stop("ars: `lower` must be a single number (-Inf allowed).")
  }
  if (!is.numeric(upper) || length(upper) != 1L || is.na(upper)) {
    stop("ars: `upper` must be a single number (Inf allowed).")
  }
  if (lower >= upper) {
    stop("ars: invalid domain: `lower` (", lower, ") must be strictly less than `upper` (",
         upper, ").")
  }
  if (any(x <= lower) || any(x >= upper)) {
    stop("ars: all values of `x` must lie strictly inside (", lower, ", ", upper, ").")
  }
  list(lower = lower, upper = upper)
}

##' Validate the number of samples to draw.
ars_validate_n <- function(n) {
  if (missing(n) || is.null(n) || length(n) != 1L) {
    stop("ars: `n` must be a single number.")
  }
  if (!is.numeric(n) || is.na(n)) {
    stop("ars: `n` must be a single, non-missing number; got ", class(n)[1L], ".")
  }
  if (is.infinite(n)) {
    stop("ars: `n` must be finite.")
  }
  if (n < 0) {
    stop("ars: `n` must be non-negative; got ", n, ".")
  }
  if (n != round(n)) {
    stop("ars: `n` must be a whole number; got ", n, ".")
  }
  as.integer(n)
}

##' Validate the numerical control parameters supplied to `ars`.
ars_validate_control <- function(maxit, tol, max_width, min_width) {
  chk <- function(v, nm) {
    if (!is.numeric(v) || length(v) != 1L || is.na(v) || v <= 0) {
      stop("ars: `", nm, "` must be a single positive number.")
    }
  }
  chk(maxit, "maxit"); chk(tol, "tol"); chk(max_width, "max_width"); chk(min_width, "min_width")
  if (min_width >= max_width) {
    stop("ars: `min_width` must be smaller than `max_width`.")
  }
  list(maxit = as.integer(maxit), tol = tol, max_width = max_width, min_width = min_width)
}

##' Validate the output file argument.
ars_validate_file <- function(file) {
  if (is.null(file)) return(NULL)
  if (!is.character(file) || length(file) != 1L || is.na(file) || !nzchar(file)) {
    stop("ars: `file` must be NULL or a single non-empty file name.")
  }
  file
}


## =============================================================================
## 2. Log density evaluation and log-concavity checking
## =============================================================================

##' Evaluate the log density, giving a clear error if the user function fails.
ars_eval_logdensity <- function(f, x) {
  v <- tryCatch(f(x), error = function(e) {
    stop("ars: the density function failed when evaluated at ",
         paste(format(signif(x, 6)), collapse = ", "), ": ", conditionMessage(e))
  })
  v <- .ars_safe_numeric(v, x)
  v[is.nan(v)] <- NA_real_
  v
}

##' Check log-concavity *locally* by verifying that the slope of the log density
##' is non-increasing, i.e. that the secant slopes between successive
##' evaluation points `s_i = (h(x_{i+1}) - h(x_i)) / (x_{i+1} - x_i)` satisfy
##' `s_i >= s_{i+1}` (second difference of `h` is <= 0).
##'
##' This is the discrete analogue of Gilks & Wild's assumption that h is
##' concave with continuous derivative.  It is the check applied repeatedly
##' *during sampling* -- after each batch of newly added hull points -- so that
##' any observed non-log-concavity aborts the sampler with an informative error.
##'
##' @param x Numeric vector of evaluation points (sorted, length >= 3).
##' @param h Log density evaluated at `x`.
##' @param tol Numerical tolerance for the slope comparison.
##' @param context Description used in the error message.
##' @return TRUE invisibly; errors if concavity is violated.
ars_is_log_concave <- function(x, h, tol = 1e-8, context = "log density") {
  x <- as.numeric(x)
  h <- as.numeric(h)
  if (length(x) < 3L) return(invisible(TRUE))
  if (anyNA(h) || any(!is.finite(h))) {
    stop("ars: the ", context, " must be finite at every evaluation point used to build the hull.")
  }
  slopes <- diff(h) / diff(x)
  dslopes <- diff(slopes)
  scale <- pmax(1, abs(slopes[-1L]) + abs(slopes[-length(slopes)]))
  bad <- which(dslopes > tol * scale)
  if (length(bad)) {
    i <- bad[1L]
    stop("ars: the ", context, " is not log-concave: the slopes of the log density increase ",
         "between x = ", format(signif(x[i], 6)), " and x = ", format(signif(x[i + 2L], 6)),
         " (slopes ", format(signif(slopes[i], 6)), " then ",
         format(signif(slopes[i + 1L], 6)), "). ",
         "Adaptive rejection sampling requires a log-concave density.")
  }
  invisible(TRUE)
}

##' Numerical derivative of the log density (central differences).
ars_logdensity_derivative <- function(f, x) {
  hstep <- 1e-5 * pmax(1, abs(x))
  fplus <- ars_eval_logdensity(f, x + hstep)
  fminus <- ars_eval_logdensity(f, x - hstep)
  d <- (fplus - fminus) / (2 * hstep)
  bad <- !is.finite(d)
  if (any(bad)) {
    stop("ars: could not compute the derivative of the log density at x = ",
         paste(format(signif(x[bad], 6)), collapse = ", "),
         ". Check that the density is strictly positive and well behaved there.")
  }
  d
}


## =============================================================================
## 3. Hull construction and sampling
## =============================================================================

##' Build the initial adaptive-hull state from the starting abscissae.
##'
##' The state is an environment (so the hull can grow cheaply during sampling)
##' with components
##'   f            -- log density function
##'   lower, upper -- support bounds (possibly infinite)
##'   x            -- sorted abscissae
##'   h            -- log density at `x`
##'   hprime       -- derivative of the log density at `x`
##'   z            -- hull breakpoints, length(x) + 1 (z[1] = lower, z[k+1] = upper)
##'   n_added      -- number of points added during sampling
ars_init_hull <- function(f, x, lower, upper) {
  h <- ars_eval_logdensity(f, x)
  hp <- ars_logdensity_derivative(f, x)
  ars_is_log_concave(x, h, context = "log density at the starting points")

  state <- new.env(parent = emptyenv())
  state$f <- f
  state$lower <- lower
  state$upper <- upper
  state$x <- as.numeric(x)
  state$h <- h
  state$hprime <- hp
  state$n_added <- 0L
  state$z <- ars_hull_breakpoints(lower, upper, x, h, hp)
  ars_check_hull(state)
  state
}

##' Breakpoints of the tangent (upper-hull) piecewise linear approximation.
##'
##' Intersection of the tangents at x_i and x_{i+1}:
##'   z_{i+1} = (h(x_{i+1}) - x_{i+1} h'(x_{i+1}) - h(x_i) + x_i h'(x_i)) /
##'             (h'(x_i) - h'(x_{i+1}))
ars_hull_breakpoints <- function(lower, upper, x, h, hprime) {
  k <- length(x)
  mid <- numeric(max(k - 1L, 0L))
  if (k > 1L) {
    for (i in seq_len(k - 1L)) {
      denom <- hprime[i] - hprime[i + 1L]
      if (abs(denom) < 1e-12) {
        mid[i] <- (x[i] + x[i + 1L]) / 2
      } else {
        mid[i] <- (h[i + 1L] - x[i + 1L] * hprime[i + 1L] - h[i] + x[i] * hprime[i]) / denom
      }
    }
  }
  c(lower, mid, upper)
}

##' Verify that the hull is a valid upper bound: breakpoints increasing, and
##' each tangent non-negative at both ends of its own interval.  A failure here
##' means the log density is not concave (or the support bounds are wrong).
ars_check_hull <- function(state) {
  z <- state$z
  x <- state$x
  if (any(diff(z) < 0)) {
    stop("ars: the tangent hull is not ordered in x, which indicates that the log density ",
         "is not concave (tangent intersections are not increasing).")
  }
  n <- length(x)
  for (i in seq_len(n)) {
    left <- z[i]
    right <- z[i + 1L]
    if (right <= left) {
      stop("ars: empty hull interval around x = ", format(signif(x[i], 6)),
           "; the log density appears not to be concave (tangents cross in the wrong order).")
    }
    if (is.finite(left)) {
      v <- state$h[i] + (left - x[i]) * state$hprime[i]
      if (!is.finite(v) || v < -1e-8) {
        stop("ars: the tangent at x = ", format(signif(x[i], 6)),
             " does not bound the log density at x = ", format(signif(left, 6)),
             ", so the log density is not concave (or `lower` is above the support of the density).")
      }
    }
    if (is.finite(right)) {
      v <- state$h[i] + (right - x[i]) * state$hprime[i]
      if (!is.finite(v) || v < -1e-8) {
        stop("ars: the tangent at x = ", format(signif(x[i], 6)),
             " does not bound the log density at x = ", format(signif(right, 6)),
             ", so the log density is not concave (or `upper` is below the support of the density).")
      }
    }
  }
  invisible(TRUE)
}

##' Log of the integral of one piece of the upper hull, i.e.
##'   log int_{left}^{right} exp(h(x_i) + (t - x_i) h'(x_i)) dt ,
##' handled analytically for infinite limits.  `left`/`right` must be the
##' breakpoints bounding the piece that belongs to tangent point `xi`.
ars_piece_log_integral <- function(left, right, xi, hi, hpi) {
  ## U(t) = hi + (t - xi) * hpi = A + B t
  A <- hi - xi * hpi
  B <- hpi
  if (abs(B) < 1e-14) {
    if (!is.finite(left) || !is.finite(right)) return(Inf)
    return(A + log(right - left))
  }
  log_u_l <- if (is.finite(left)) A + B * left else if (B > 0) -Inf else Inf
  log_u_r <- if (is.finite(right)) A + B * right else if (B > 0) Inf else -Inf

  if (!is.finite(log_u_l) && !is.finite(log_u_r)) return(Inf)

  ## int = (exp(log_u_r) - exp(log_u_l)) / B
  ## Evaluate by factoring out the dominant endpoint.
  if (B > 0) {
    ## right endpoint dominates; exp(log_u_r)/B * (1 - exp(log_u_l - log_u_r))
    if (is.infinite(log_u_r)) return(Inf)
    return(log_u_r - log(B) + log1p(-exp(log_u_l - log_u_r)))
  }
  ## B < 0: exp(log_u_l)/(-B) * (1 - exp(log_u_r - log_u_l))
  if (is.infinite(log_u_l)) return(Inf)
  log_u_l - log(-B) + log1p(-exp(log_u_r - log_u_l))
}

##' Log normalising constant of the upper hull.
ars_hull_log_integral <- function(state) {
  n <- length(state$x)
  li <- vapply(seq_len(n), function(i) {
    ars_piece_log_integral(state$z[i], state$z[i + 1L], state$x[i], state$h[i], state$hprime[i])
  }, numeric(1L))
  if (anyNA(li)) {
    stop("ars: the upper hull has non-integrable pieces; the density may not be log-concave ",
         "or its support may be specified incorrectly (`lower`/`upper`).")
  }
  li
}

##' Draw `m` indices selecting which hull piece each sample comes from.
ars_sample_hull_index <- function(state, m) {
  li <- ars_hull_log_integral(state)
  n <- length(li)
  if (any(is.infinite(li))) {
    stop("ars: the normalising constant of the upper hull is infinite. The log density is ",
         "either not log-concave or is not decaying at the ends of the supplied support ",
         "(`lower`/`upper`).")
  }
  maxli <- max(li)
  w <- exp(li - maxli)
  if (!is.finite(sum(w)) || sum(w) <= 0) {
    stop("ars: could not normalise the upper hull (numerical failure).")
  }
  prob <- w / sum(w)
  cum <- cumsum(prob)
  cum[n] <- 1
  idx <- findInterval(stats::runif(m), cum) + 1L
  pmin(idx, n)
}

##' Draw `m` values from the piecewise exponential upper hull.
ars_sample_hull <- function(state, m) {
  idx <- ars_sample_hull_index(state, m)
  left <- state$z[idx]
  right <- state$z[idx + 1L]
  xi <- state$x[idx]
  hi <- state$h[idx]
  hpi <- state$hprime[idx]
  u <- stats::runif(m)
  out <- numeric(m)

  for (j in seq_len(m)) {
    l <- left[j]; r <- right[j]; s <- hpi[j]; x0 <- xi[j]
    if (abs(s) < 1e-14) {
      ## flat piece: uniform (an infinite flat piece is not integrable)
      if (!is.finite(l) || !is.finite(r)) {
        stop("ars: a flat piece of the log density has infinite length, so the hull is not ",
             "integrable.")
      }
      out[j] <- l + u[j] * (r - l)
    } else {
      ## log U(t) - log U(x0) = s (t - x0);  CDF on [l, r]:
      ##   F(t) = (exp(s(t-x0)) - exp(s(l-x0))) / (exp(s(r-x0)) - exp(s(l-x0)))
      ll <- if (is.finite(l)) s * (l - x0) else if (s > 0) -Inf else Inf
      rr <- if (is.finite(r)) s * (r - x0) else if (s > 0) Inf else -Inf
      if (is.finite(ll) && is.finite(rr)) {
        lo <- min(ll, rr); hip <- max(ll, rr)
        uu <- if (ll <= rr) u[j] else 1 - u[j]
        val <- log1p(uu * expm1(hip - lo)) + lo
        out[j] <- x0 + val / s
      } else if (is.infinite(rr)) {
        ## right end is +Inf: F(t) = exp(s (t - x0) - ll)
        out[j] <- x0 + (log(u[j]) + ll) / s
      } else {
        ## left end is -Inf: 1 - F(t) = exp(s (t - x0) - rr)
        out[j] <- x0 + (log1p(-u[j]) + rr) / s
      }
    }
  }

  if (any(!is.finite(out))) {
    stop("ars: generated a non-finite sample from the upper hull (numerical failure).")
  }
  ## keep samples strictly inside the support
  if (is.finite(state$lower)) {
    out <- pmax(out, state$lower + 1e-12 * pmax(1, abs(state$lower)))
  }
  if (is.finite(state$upper)) {
    out <- pmin(out, state$upper - 1e-12 * pmax(1, abs(state$upper)))
  }
  out
}

##' Add new abscissae to the hull.  Mutates `state` in place (its `x`, `h`,
##' `hprime`, `z` and `n_added` components are updated).
ars_update_hull <- function(state, xnew) {
  if (any(!is.finite(xnew))) {
    stop("ars: cannot add a non-finite point to the hull.")
  }
  if (any(xnew <= state$lower) || any(xnew >= state$upper)) {
    stop("ars: cannot add a point outside the support (", state$lower, ", ", state$upper, ").")
  }
  for (xv in xnew) {
    if (any(abs(state$x - xv) < 1e-12 * pmax(1, abs(xv)))) next  # already present
    hnew <- ars_eval_logdensity(state$f, xv)
    if (is.na(hnew) || !is.finite(hnew)) {
      stop("ars: the log density is not finite at the new hull point x = ",
           format(signif(xv, 6)),
           ". The density must be strictly positive on its support.")
    }
    hpnew <- ars_logdensity_derivative(state$f, xv)
    pos <- findInterval(xv, state$x) + 1L
    state$x <- append(state$x, xv, after = pos - 1L)
    state$h <- append(state$h, hnew, after = pos - 1L)
    state$hprime <- append(state$hprime, hpnew, after = pos - 1L)
    state$n_added <- state$n_added + 1L
  }
  ## the log-concavity check performed *during* sampling
  ars_is_log_concave(state$x, state$h,
                     context = "log density (after adding a point to the hull)")
  state$z <- ars_hull_breakpoints(state$lower, state$upper, state$x, state$h, state$hprime)
  ars_check_hull(state)
  invisible(state)
}

##' Log of the lower (squeezing) hull at `x`: the chord between the abscissae
##' bracketing `x`.  Outside [min(x), max(x)] there is no squeeze, so -Inf.
ars_squeeze_log <- function(state, x) {
  xs <- state$x
  res <- rep(-Inf, length(x))
  k <- length(xs)
  if (k < 2L) return(res)
  idx <- findInterval(x, xs)
  inside <- idx >= 1L & idx < k
  if (any(inside)) {
    i <- idx[inside]
    sl <- (state$h[i + 1L] - state$h[i]) / (xs[i + 1L] - xs[i])
    res[inside] <- state$h[i] + (x[inside] - xs[i]) * sl
  }
  res
}

##' Log of the upper (tangent) hull at `x`.
ars_upper_log <- function(state, x) {
  xs <- state$x
  idx <- findInterval(x, state$z)
  idx <- pmin(pmax(idx, 1L), length(xs))
  state$h[idx] + (x - xs[idx]) * state$hprime[idx]
}


## =============================================================================
## 4. Main sampler
## =============================================================================

##' Adaptive rejection sampler for log-concave densities (Gilks & Wild, 1992).
##'
##' @param n Number of samples required (non-negative whole number).
##' @param dfun Density: a vectorised function of one argument (e.g. `dnorm`,
##'   `dexp`, a user function), the name of such a function, or a string
##'   expression in `x` giving a possibly unnormalised density.
##' @param x Optional numeric vector of starting abscissae, strictly inside the
##'   support.  If missing, sensible defaults are derived from `lower`/`upper`.
##' @param lower,upper Support bounds; may be infinite (the log density must
##'   decay there).  Default `-Inf`, `Inf`.
##' @param log Logical; TRUE if `dfun` already returns a log density.
##' @param ... Further arguments passed to `dfun` (e.g. `sd`, `rate`).
##' @param file Optional file name; if given the samples are written there
##'   (one value per line) as a side effect.
##' @param maxit Maximum number of hull points that may be added.
##' @param tol Tolerance used in the log-concavity check.
##' @param max_width,min_width Control the automatic choice of starting points.
##' @param verbose Print a short report.
##' @return A numeric vector of length `n` of class `"ars"` with attributes
##'   `n_added`, `n_rejected`, `n_squeezed`, `hull_x` and `call`.
ars <- function(n, dfun, x = NULL, lower = -Inf, upper = Inf, log = FALSE, ...,
                file = NULL, maxit = 500L, tol = 1e-8,
                max_width = 1, min_width = 1e-3, verbose = FALSE) {
  call <- match.call()

  ## ---- input validation --------------------------------------------------
  n <- ars_validate_n(n)
  ctl <- ars_validate_control(maxit, tol, max_width, min_width)
  file <- ars_validate_file(file)
  if (!is.logical(log) || length(log) != 1L || is.na(log)) {
    stop("ars: `log` must be TRUE or FALSE.")
  }
  if (!is.logical(verbose) || length(verbose) != 1L || is.na(verbose)) {
    stop("ars: `verbose` must be TRUE or FALSE.")
  }
  f <- ars_make_logdensity(dfun, log = log, ...)

  if (n == 0L) {
    out <- structure(numeric(0), class = "ars", n_added = 0L, n_rejected = 0L,
                     n_squeezed = 0L, hull_x = numeric(0), call = call)
    return(out)
  }

  if (is.null(x)) {
    x <- ars_default_x(f, lower, upper, max_width = ctl$max_width,
                       min_width = ctl$min_width)
  } else {
    x <- ars_validate_x(x)
  }
  if (length(x) < 2L) {
    ## at least two abscissae are needed to build a hull
    extra <- x[1L] + ctl$max_width
    x <- sort(unique(c(x, extra)))
    if (length(x) < 2L) {
      stop("ars: at least two distinct starting points are required; please supply `x`.")
    }
  }
  bnd <- ars_validate_bounds(lower, upper, x)
  lower <- bnd$lower; upper <- bnd$upper

  ## ---- initial hull (also checks log-concavity) --------------------------
  state <- ars_init_hull(f, x, lower, upper)

  ## ---- adaptive rejection loop ------------------------------------------
  out <- numeric(n)
  filled <- 0L
  n_rejected <- 0L
  n_squeezed <- 0L
  attempts <- 0L
  max_attempts <- 100L * n + 1000L

  while (filled < n) {
    attempts <- attempts + 1L
    if (attempts > max_attempts) {
      stop("ars: giving up after ", attempts, " rejection-sampling attempts. ",
           "The supplied density may not be log-concave.")
    }
    m <- n - filled
    cand <- ars_sample_hull(state, m)

    ## validity checks on the candidates
    log_target <- ars_eval_logdensity(f, cand)
    bad <- is.na(log_target) | !is.finite(log_target)
    if (any(bad)) {
      stop("ars: the log density is not finite at candidate point(s) x = ",
           paste(format(signif(cand[bad], 6)), collapse = ", "),
           ". The density must be strictly positive on its support, and `lower`/`upper` ",
           "must bound that support correctly.")
    }
    log_upper <- ars_upper_log(state, cand)
    above <- log_target > log_upper + 1e-6 * pmax(1, abs(log_upper))
    if (any(above)) {
      stop("ars: the log density exceeded its tangent upper hull at x = ",
           paste(format(signif(cand[above], 6)), collapse = ", "),
           "; the density is not log-concave.")
    }
    log_squeeze <- ars_squeeze_log(state, cand)
    u <- log(stats::runif(m))

    ## squeezed acceptance (no evaluation of the target needed)
    squeezed <- is.finite(log_squeeze) & u <= log_squeeze - log_upper
    n_squeezed <- n_squeezed + sum(squeezed)

    accepted <- squeezed
    need <- !squeezed
    if (any(need)) {
      log_accept <- u[need] <= log_target[need] - log_upper[need]
      accepted[which(need)[log_accept]] <- TRUE
      ## rejected candidates become new hull points (the adaptive step)
      rej <- which(need)[!log_accept]
      if (length(rej)) {
        n_rejected <- n_rejected + length(rej)
        if (state$n_added + length(rej) > ctl$maxit) {
          stop("ars: the maximum number of hull points (", ctl$maxit, ") was reached. ",
               "The density may not be log-concave, or the support bounds may be too wide.")
        }
        ars_update_hull(state, cand[rej])
      }
    }

    take <- which(accepted)
    if (length(take)) {
      k <- min(length(take), n - filled)
      out[filled + seq_len(k)] <- cand[take[seq_len(k)]]
      filled <- filled + k
    }
  }

  out <- structure(out, class = "ars",
                   n_added = state$n_added,
                   n_rejected = n_rejected,
                   n_squeezed = n_squeezed,
                   hull_x = state$x,
                   call = call)

  if (!is.null(file)) {
    ars_write_samples(out, file)
  }
  if (verbose) {
    cat(sprintf("ars: drew %d samples; %d hull points added, %d rejections, %d squeeze acceptances.\n",
                n, state$n_added, n_rejected, n_squeezed))
  }
  out
}

##' Choose reasonable starting abscissae when the user does not supply `x`.
##' We start at 0 (or the middle of a finite support) and walk outwards while
##' the log density stays within 30 of its maximum.
ars_default_x <- function(f, lower, upper, max_width = 1, min_width = 1e-3) {
  start <- if (is.finite(lower) && is.finite(upper)) {
    (lower + upper) / 2
  } else if (is.finite(lower)) {
    lower + max_width
  } else if (is.finite(upper)) {
    upper - max_width
  } else {
    0
  }
  if (start <= lower || start >= upper) {
    stop("ars: the domain is too narrow to place a starting point; please supply `x`.")
  }
  xs <- c(start, start - max_width / 2, start + max_width / 2)
  xs <- sort(unique(xs[xs > lower & xs < upper]))
  h <- ars_eval_logdensity(f, xs)
  if (all(!is.finite(h))) {
    stop("ars: the log density is not finite at the default starting point x = ",
         format(signif(start, 6)),
         ". Please supply `x` (strictly inside the support) and check `lower`/`upper`.")
  }
  ok <- is.finite(h)
  xs <- xs[ok]; h <- h[ok]
  if (length(xs) < 2L) {
    stop("ars: could not find two usable starting points; please supply `x`.")
  }
  for (side in c(-1, 1)) {
    step <- max_width
    while (step >= min_width) {
      cand <- if (side < 0) min(xs) - step else max(xs) + step
      if (cand <= lower || cand >= upper) break
      hc <- ars_eval_logdensity(f, cand)
      if (!is.finite(hc) || hc < max(h) - 30) break
      xs <- sort(c(xs, cand))
      h <- ars_eval_logdensity(f, xs)
      step <- max_width
    }
  }
  if (length(xs) < 2L) {
    stop("ars: could not find two usable starting points; please supply `x`.")
  }
  xs
}


## =============================================================================
## 5. Summaries and file output
## =============================================================================

##' Summary statistics of an `ars` sample.
ars_summary <- function(samples) {
  s <- as.numeric(samples)
  list(n = length(s),
       mean = mean(s),
       sd = if (length(s) > 1L) stats::sd(s) else NA_real_,
       min = min(s), max = max(s),
       median = stats::median(s),
       n_added = attr(samples, "n_added"),
       n_rejected = attr(samples, "n_rejected"))
}

print.ars <- function(x, ...) {
  s <- ars_summary(x)
  cat("Adaptive rejection sample\n")
  cat(sprintf("  n        : %d\n", s$n))
  cat(sprintf("  mean     : %.6f\n", s$mean))
  cat(sprintf("  sd       : %.6f\n", s$sd))
  cat(sprintf("  range    : [%.6f, %.6f]\n", s$min, s$max))
  cat(sprintf("  hull pts : %d added, %d rejections\n", s$n_added, s$n_rejected))
  invisible(x)
}

##' Write samples to a plain text file, one value per line.
ars_write_samples <- function(samples, file) {
  file <- ars_validate_file(file)
  con <- tryCatch(base::file(file, "w"), error = function(e) {
    stop("ars: cannot open '", file, "' for writing: ", conditionMessage(e))
  })
  on.exit(close(con), add = TRUE)
  writeLines(format(as.numeric(samples), digits = 15, trim = TRUE), con)
  invisible(file)
}


## =============================================================================
## 6. Formal testing
## =============================================================================

.ars_test_state <- new.env(parent = emptyenv())
.ars_test_state$results <- list()

##' Print "NAME: PASS" / "NAME: FAIL" plus details and statistics.
.ars_report <- function(name, passed, details = NULL, stats = NULL) {
  status <- if (isTRUE(passed)) "PASS" else "FAIL"
  cat(sprintf("%s: %s\n", name, status))
  if (!is.null(details)) cat(sprintf("    %s\n", details))
  if (!is.null(stats)) {
    for (nm in names(stats)) {
      cat(sprintf("    %-16s = %s\n", nm, format(signif(stats[[nm]], 6))))
    }
  }
  .ars_test_state$results[[name]] <- isTRUE(passed)
  invisible(isTRUE(passed))
}

##' Evaluate an expression, returning whether an error was raised and its
##' message.
.ars_expect_error <- function(expr) {
  tryCatch({
    force(expr)
    list(ok = FALSE, msg = "no error was raised")
  }, error = function(e) list(ok = TRUE, msg = conditionMessage(e)))
}

##' Compare the sample mean and sd with the theoretical values.  Because the
##' samples are genuinely random, the mean is tested with a z-test at a wide
##' tolerance (default 4 standard errors, so the false-rejection probability is
##' about 6e-5) and the sd with a 10% relative tolerance.  Both are far tighter
##' than the ~40% discrepancy a sampler returning the wrong shape would show.
.ars_check_moments <- function(x, true_mean, true_sd, label, n_sd = 4, rel_sd_tol = 0.1) {
  n <- length(x)
  m <- mean(x)
  s <- stats::sd(x)
  se <- true_sd / sqrt(n)
  z <- (m - true_mean) / se
  passed <- abs(z) <= n_sd && abs(s / true_sd - 1) <= rel_sd_tol
  .ars_report(label, passed,
    details = sprintf(paste0("mean %.4f vs true %.4f (z = %.2f, tolerance |z| <= %.1f); ",
                             "sd %.4f vs true %.4f (rel. tolerance %.0f%%)"),
                      m, true_mean, z, n_sd, s, true_sd, 100 * rel_sd_tol),
    stats = c(sample_mean = m, sample_sd = s, true_mean = true_mean, true_sd = true_sd))
  passed
}

##' Kolmogorov-Smirnov goodness of fit against the exact CDF.  The sample is
##' compared with 100 equally sized subsamples of the truth; the test rejects
##' at level 0.001 so that passing is robust to the random seed.
.ars_check_ks <- function(x, cdf, label, tolerance = 0.001) {
  test <- suppressWarnings(stats::ks.test(x, cdf))
  passed <- test$p.value > tolerance
  .ars_report(label, passed,
    details = sprintf("KS statistic %.5f, p-value %.4f (must exceed %.3f)",
                      test$statistic, test$p.value, tolerance),
    stats = c(ks_statistic = as.numeric(test$statistic), ks_p_value = test$p.value))
  passed
}

##' The formal test suite.  Prints one "NAME: PASS" / "NAME: FAIL" line per
##' test with informative statistics, and returns (invisibly) a named logical
##' vector of results.
##'
##' @param write_files If TRUE, write /app/normal_samples.txt and
##'   /app/exponential_samples.txt.
##' @param n Number of samples used by the distributional tests.
##' @param seed Random seed, so that runs are reproducible.
test <- function(write_files = TRUE, n = 20000L, seed = 20240517L) {
  .ars_test_state$results <- list()
  n <- ars_validate_n(n)
  cat("================================================================\n")
  cat(" Testing the adaptive rejection sampler (Gilks & Wild, 1992)\n")
  cat("================================================================\n\n")

  set.seed(seed)

  ## ------------------------------------------------------- helper modules
  cat("-- Auxiliary functions -----------------------------------------\n")

  r <- .ars_expect_error(
    ars_is_log_concave(c(-2, -1, 0, 1, 2), dcauchy(c(-2, -1, 0, 1, 2), log = TRUE)))
  .ars_report("log_concavity_detects_cauchy", r$ok, details = r$msg)

  ok_concave <- isTRUE(tryCatch({
    ars_is_log_concave(c(-2, -1, 0, 1, 2), dnorm(c(-2, -1, 0, 1, 2), log = TRUE)); TRUE
  }, error = function(e) FALSE))
  .ars_report("log_concavity_accepts_normal", ok_concave,
              details = "a concave log density must not be flagged")

  ok_exp <- isTRUE(tryCatch({
    ars_is_log_concave(c(0.5, 1, 2, 4, 8), dexp(c(0.5, 1, 2, 4, 8), log = TRUE)); TRUE
  }, error = function(e) FALSE))
  .ars_report("log_concavity_accepts_exponential", ok_exp)

  bimodal <- function(x) log(0.5 * dnorm(x, -3, 1) + 0.5 * dnorm(x, 3, 1))
  r <- .ars_expect_error(ars_is_log_concave(seq(-5, 5, by = 1), bimodal(seq(-5, 5, by = 1))))
  .ars_report("log_concavity_detects_bimodal", r$ok, details = r$msg)

  f <- ars_make_logdensity("exp(-x^2/2)")
  val <- f(0)
  .ars_report("expression_input_parsed", isTRUE(all.equal(as.numeric(val), 0)),
              details = sprintf("log density at x = 0 is %.6f (expected 0)", val))
  vec <- f(c(-1, 0, 1))
  .ars_report("expression_input_vectorised", length(vec) == 3L,
              details = sprintf("returned %d values for 3 inputs", length(vec)))

  f1 <- ars_make_logdensity(dnorm)
  f2 <- ars_make_logdensity("dnorm")
  agree <- isTRUE(all.equal(f1(c(-1, 0, 2)), f2(c(-1, 0, 2))))
  .ars_report("density_from_function_and_name", agree,
              details = "dnorm() and \"dnorm\" give identical log densities")

  f_log <- ars_make_logdensity(function(x) dnorm(x, log = TRUE), log = TRUE)
  agree <- isTRUE(all.equal(f_log(c(-1, 0, 2)), dnorm(c(-1, 0, 2), log = TRUE)))
  .ars_report("log_density_input", agree,
              details = "log = TRUE input gives the same values as dnorm(log = TRUE)")

  r <- .ars_expect_error(ars_make_logdensity(function(x) sum(x)))
  .ars_report("non_vectorised_density_rejected", r$ok, details = r$msg)

  ## ------------------------------------------------------------ validation
  cat("\n-- Input validation --------------------------------------------\n")

  r <- .ars_expect_error(ars(-5, dnorm, x = c(-1, 1)))
  .ars_report("reject_negative_n", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(2.5, dnorm, x = c(-1, 1)))
  .ars_report("reject_fractional_n", r$ok, details = r$msg)

  r <- .ars_expect_error(ars("10", dnorm, x = c(-1, 1)))
  .ars_report("reject_non_numeric_n", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 1), lower = 2, upper = 1))
  .ars_report("reject_invalid_domain", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 5), lower = -Inf, upper = 2))
  .ars_report("reject_x_outside_support", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(0, 0, 0)))
  .ars_report("reject_degenerate_x", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, NA)))
  .ars_report("reject_NA_in_x", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, "not_a_function_or_expression((("))
  .ars_report("reject_bad_density_input", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 1), file = 42))
  .ars_report("reject_bad_file_argument", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(10, dnorm, x = c(-1, 1), maxit = -3))
  .ars_report("reject_bad_control_argument", r$ok, details = r$msg)

  z <- tryCatch(ars(0, dnorm), error = function(e) e)
  .ars_report("accept_zero_n", is.numeric(z) && length(z) == 0L,
              details = "ars(0, dnorm) returns a length-0 numeric vector")

  ## ---------------------------------------------- non log-concave inputs
  cat("\n-- Non log-concave densities -----------------------------------\n")

  r <- .ars_expect_error(ars(100, dcauchy, x = c(-1, 0.5, 1)))
  .ars_report("reject_cauchy_density", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(100, bimodal, x = c(-4, -2, 2, 4)))
  .ars_report("reject_bimodal_density", r$ok, details = r$msg)

  r <- .ars_expect_error(ars(100, function(x) dnorm(x, 0, 1) - 0.2,
                             x = c(-1, 0, 1), lower = -10, upper = 10))
  .ars_report("reject_density_negative_on_support", r$ok, details = r$msg)

  ## --------------------------------------------------- truth: N(0, 1)
  cat(sprintf("\n-- Normal(0, 1), %d samples -----------------------------------\n", n))
  s_norm <- ars(n, dnorm, x = c(-1.5, 0, 1.5))
  .ars_check_moments(s_norm, 0, 1, "normal_mean_sd")
  .ars_check_ks(s_norm, pnorm, "normal_ks_test")
  .ars_report("normal_all_finite", all(is.finite(s_norm)) && length(s_norm) == n,
              details = sprintf("all %d samples are finite", n))
  .ars_report("normal_hull_adaptive", attr(s_norm, "n_added") > 0L,
              details = sprintf("%d hull points added during sampling", attr(s_norm, "n_added")))

  qs <- as.numeric(stats::quantile(s_norm, c(0.01, 0.25, 0.5, 0.75, 0.99)))
  truth <- stats::qnorm(c(0.01, 0.25, 0.5, 0.75, 0.99))
  .ars_report("normal_quantiles", all(abs(qs - truth) < 0.05),
              details = paste(sprintf("q[%s]: %.4f vs %.4f", c("1%", "25%", "50%", "75%", "99%"),
                                      qs, truth), collapse = "; "))

  ## a sampler returning uniform draws on the observed range would have
  ## sd ~ range / sqrt(12); check the shape is normal and not uniform
  range_sd <- (max(s_norm) - min(s_norm)) / sqrt(12)
  .ars_report("normal_not_uniform_shape", abs(stats::sd(s_norm) - range_sd) > 0.3,
              details = sprintf(paste0("sample sd %.4f; a uniform distribution on the observed ",
                                       "range [%.2f, %.2f] would have sd %.4f"),
                                stats::sd(s_norm), min(s_norm), max(s_norm), range_sd))

  ## ------------------------------------------------- truth: Exp(rate = 2)
  cat(sprintf("\n-- Exponential(rate = 2) on (0, Inf), %d samples ---------------\n", n))
  s_exp <- ars(n, dexp, x = c(0.2, 0.7, 1.5), lower = 0, rate = 2)
  .ars_check_moments(s_exp, 1 / 2, 1 / 2, "exponential_mean_sd")
  .ars_check_ks(s_exp, function(p) pexp(p, rate = 2), "exponential_ks_test")
  .ars_report("exponential_positive_support", all(s_exp > 0),
              details = sprintf("minimum sample %.5f > 0", min(s_exp)))
  .ars_report("exponential_skewed_shape", abs(stats::median(s_exp) / (log(2) / 2) - 1) < 0.05,
              details = sprintf("sample median %.4f vs true %.4f (a symmetric sampler would differ)",
                                stats::median(s_exp), log(2) / 2))

  ## ------------------------------------- truth: truncated N(0,1) on (-1,2)
  cat(sprintf("\n-- Truncated N(0,1) on (-1, 2), %d samples --------------------\n", n))
  a <- -1; b <- 2
  Z <- pnorm(b) - pnorm(a)
  tn_mean <- (dnorm(a) - dnorm(b)) / Z
  tn_sd <- sqrt(1 + (a * dnorm(a) - b * dnorm(b)) / Z - tn_mean^2)
  s_trunc <- ars(n, dnorm, x = c(-0.5, 0, 0.5), lower = a, upper = b)
  .ars_check_moments(s_trunc, tn_mean, tn_sd, "truncated_normal_mean_sd")
  .ars_check_ks(s_trunc, function(p) (pnorm(p) - pnorm(a)) / Z, "truncated_normal_ks_test")
  .ars_report("truncated_normal_in_bounds", all(s_trunc > a & s_trunc < b),
              details = sprintf("range [%.4f, %.4f] lies inside (-1, 2)",
                                min(s_trunc), max(s_trunc)))

  ## ---------------------------------------- truth: unnormalised expression
  cat(sprintf("\n-- Unnormalised density exp(-x^2/2), %d samples ---------------\n", n))
  s_expr <- ars(n, "exp(-x^2/2)", x = c(-1, 0, 1))
  .ars_check_moments(s_expr, 0, 1, "unnormalised_expression_mean_sd")

  ## ------------------------------------------- truth: Gamma(shape = 3, rate = 1)
  cat(sprintf("\n-- Gamma(shape = 3, rate = 1), %d samples ---------------------\n", n))
  s_gam <- ars(n, dgamma, x = c(1, 2, 3), lower = 0, shape = 3, rate = 1)
  .ars_check_moments(s_gam, 3, sqrt(3), "gamma_mean_sd")
  .ars_check_ks(s_gam, function(p) pgamma(p, shape = 3, rate = 1), "gamma_ks_test")

  ## -------------------------------------------------------- sample files
  cat("\n-- Sample files ------------------------------------------------\n")
  if (write_files) {
    ok_norm <- isTRUE(tryCatch({
      ars_write_samples(s_norm, "/app/normal_samples.txt"); TRUE
    }, error = function(e) FALSE))
    ok_exp <- isTRUE(tryCatch({
      ars_write_samples(s_exp, "/app/exponential_samples.txt"); TRUE
    }, error = function(e) FALSE))
    chk_norm <- ok_norm && file.exists("/app/normal_samples.txt") &&
      length(readLines("/app/normal_samples.txt")) == length(s_norm)
    chk_exp <- ok_exp && file.exists("/app/exponential_samples.txt") &&
      length(readLines("/app/exponential_samples.txt")) == length(s_exp)
    .ars_report("write_normal_samples_file", chk_norm, details = "/app/normal_samples.txt")
    .ars_report("write_exponential_samples_file", chk_exp, details = "/app/exponential_samples.txt")

    tmpfile <- tempfile()
    invisible(ars(1000, dnorm, x = c(-1, 1), file = tmpfile))
    .ars_report("ars_file_argument_writes",
                file.exists(tmpfile) && length(readLines(tmpfile)) == 1000,
                details = "1000 lines written to a temporary file via `file =`")
    unlink(tmpfile)
  }

  ## ------------------------------------------------------------- summary
  res <- unlist(.ars_test_state$results)
  cat("\n================================================================\n")
  cat(sprintf(" %d of %d tests passed\n", sum(res), length(res)))
  if (all(res)) {
    cat(" ALL TESTS PASSED\n")
  } else {
    cat(" FAILED TESTS:", paste(names(res)[!res], collapse = ", "), "\n")
  }
  cat("================================================================\n")
  invisible(res)
}


## =============================================================================
## Run the tests when this file is executed directly:  Rscript ars.R
## =============================================================================
if (!interactive() && sys.nframe() == 0L) {
  test()
}
"}

{"path": "/app/ars.R", "content": "## =============================================================================
##  ars.R -- Adaptive Rejection Sampling (Gilks & Wild, 1992)
##
##  Gilks, W. R. & Wild, P. (1992). Adaptive rejection sampling for Gibbs
##  sampling. Journal of the Royal Statistical Society, Series C (Applied
##  Statistics), 41(2), 337-348.
##
##  ARS samples from a distribution whose *log* density is concave, using an
##  adaptive upper hull built from tangents to the log density and a lower
##  squeezing hull built from the chords between the tangent points.
##
##  Layout of this file
##    1. Input validation helpers      (ars_validate_*)
##    2. Log-density evaluation        (ars_eval_logdensity, ars_is_log_concave)
##    3. Hull construction / sampling  (ars_init_hull, ars_update_hull,
##                                      ars_sample_hull, ars_hull_log_integral)
##    4. Main sampler                  (ars)
##    5. Sample summary / file output  (ars_summary, ars_write_samples)
##    6. Formal tests                  (test)
##
##  Style conventions
##    * every public object is prefixed with `ars_` (or is `ars` / `test`);
##    * every helper returns a value rather than modifying state in place,
##      except `ars_update_hull()` and `ars_do_sample()` which are documented
##      as mutating their environment argument in place;
##    * user-facing problems are signalled with `stop()` and a message starting
##      with "ars: " (or "ars_<helper>: " for the helpers).
## =============================================================================


## =============================================================================
## 1. Input validation
## =============================================================================

##' Convert a user supplied density into a vectorised log-density function.
##'
##' @param dfun Either (a) a function (or a function name given as a string) of
##'   one argument that must be vectorised in that argument -- e.g. `dnorm`,
##'   `dexp`, `"dgamma"`; or (b) a single expression / string written in terms
##'   of `x`, giving a possibly unnormalised density, e.g. `"exp(-x^2)"`.
##' @param log Logical; TRUE if `dfun` is already a log density.
##' @param ... Further fixed arguments passed to `dfun` (e.g. `sd = 2`).
##' @return A function of one numeric vector argument returning log density.
ars_make_logdensity <- function(dfun, log = FALSE, ...) {
  dots <- list(...)

  if (is.character(dfun)) {
    if (length(dfun) != 1L) {
      stop("ars: `dfun` must be a single function name or a single expression when given as a string.")
    }
    fn <- if (exists(dfun, mode = "function")) {
      get(dfun, mode = "function")
    } else {
      NULL
    }
    if (!is.null(fn)) {
      dfun <- fn
    } else {
      ## treat the string as an expression in `x`
      expr <- try(parse(text = dfun)[[1L]], silent = TRUE)
      if (inherits(expr, "try-error")) {
        stop("ars: `dfun` is neither the name of a known function nor a valid expression in `x`: ",
             dfun)
      }
      dfun <- function(x) eval(expr, list(x = x))
      if (log) {
        return(function(x) as.numeric(dfun(x)))
      }
      return(function(x) {
        v <- suppressWarnings(as.numeric(dfun(x)))
        log(v)
      })
    }
  }

  if (!is.function(dfun)) {
    stop("ars: `dfun` must be a function, a function name, or an expression in `x`; got ",
         class(dfun)[1L], ".")
  }

  forced <- function(x) {
    if (length(dots)) do.call(dfun, c(list(x), dots)) else dfun(x)
  }

  ## Test vectorisation on a small probe.  A density that silently returns a
  ## single value for a vector argument is not usable by ARS.
  if (log) {
    f <- function(x) .ars_safe_numeric(forced(x), x)
    probe <- f(c(-0.5, 0, 0.5))
    if (length(probe) != 3L) {
      stop("ars: `dfun` does not appear to be vectorised (it does not return one value per input).")
    }
    return(f)
  }

  ## When `dfun` is a "d"-style density we can get log dnorm() directly, which
  ## avoids underflow for far tail evaluations.  We only do this for functions
  ## that accept a `log` argument.
  has_log_arg <- "log" %in% names(formals(dfun))
  f <- function(x) {
    v <- if (has_log_arg) {
      .ars_safe_numeric(do.call(dfun, c(list(x, log = TRUE), dots)), x)
    } else {
      v <- .ars_safe_numeric(forced(x), x)
      log(v)
    }
    if (has_log_arg) v else v
  }
  probe <- f(c(-0.5, 0, 0.5))
  if (length(probe) != 3L) {
    stop("ars: `dfun` does not appear to be vectorised (it does not return one value per input).")
  }
  f
}

##' Coerce the output of a user density to a numeric vector of `length(x)`,
##' giving a clear error if that is impossible.
.ars_safe_numeric <- function(value, x) {
  value <- suppressWarnings(as.numeric(value))
  if (length(value) == 1L && length(x) > 1L) {
    value <- rep(value, length(x))
  }
  if (length(value) != length(x)) {
    stop("ars: the density function must be vectorised: it returned ", length(value),
         " value(s) for ", length(x), " input value(s).")
  }
  value
}

##' Validate the `x` argument (the support / starting points).
ars_validate_x <- function(x) {
  if (missing(x) || is.null(x) || length(x) == 0L) {
    stop("ars: `x` must supply at least one point in the support of the density.")
  }
  if (!is.numeric(x)) {
    stop("ars: `x` must be numeric; got ", class(x)[1L], ".")
  }
  if (anyNA(x) || any(is.nan(x))) {
    stop("ars: `x` must not contain NA or NaN.")
  }
  if (any(is.infinite(x))) {
    stop("ars: `x` must be finite (support bounds are supplied through `lower`/`upper`).")
  }
  if (anyDuplicated(x)) {
    x <- unique(x)
    warning("ars: duplicated values in `x` were removed.")
  }
  sort(x)
}

##' Validate the support bounds `lower` and `upper`.
ars_validate_bounds <- function(lower, upper, x) {
  if (!is.numeric(lower) || length(lower) != 1L || is.na(lower)) {
    stop("ars: `lower` must be a single number (-Inf allowed).")
  }
  if (!is.numeric(upper) || length(upper) != 1L || is.na(upper)) {
    stop("ars: `upper` must be a single number (Inf allowed).")
  }
  if (lower >= upper) {
    stop("ars: invalid domain: `lower` (", lower, ") must be strictly less than `upper` (", upper, ").")
  }
  if (any(x <= lower) || any(x >= upper)) {
    stop("ars: all values of `x` must lie strictly inside (", lower, ", ", upper, ").")
  }
  list(lower = lower, upper = upper)
}

##' Validate the number of samples to draw.
ars_validate_n <- function(n) {
  if (missing(n) || length(n) != 1L) {
    stop("ars: `n` must be a single number.")
  }
  if (!is.numeric(n) || is.na(n)) {
    stop("ars: `n` must be a single, non-missing number; got ", class(n)[1L], ".")
  }
  if (n < 0) {
    stop("ars: `n` must be non-negative; got ", n, ".")
  }
  if (is.infinite(n)) {
    stop("ars: `n` must be finite.")
  }
  if (n != round(n)) {
    stop("ars: `n` must be a whole number; got ", n, ".")
  }
  as.integer(n)
}

##' Validate the numerical control parameters supplied to `ars`.
ars_validate_control <- function(maxit, tol, max_width, min_width) {
  if (!is.numeric(maxit) || length(maxit) != 1L || is.na(maxit) || maxit < 1) {
    stop("ars: `maxit` must be a single positive number.")
  }
  if (!is.numeric(tol) || length(tol) != 1L || is.na(tol) || tol <= 0) {
    stop("ars: `tol` must be a single positive number.")
  }
  if (!is.numeric(max_width) || length(max_width) != 1L || is.na(max_width) || max_width <= 0) {
    stop("ars: `max_width` must be a single positive number.")
  }
  if (!is.numeric(min_width) || length(min_width) != 1L || is.na(min_width) || min_width <= 0) {
    stop("ars: `min_width` must be a single positive number.")
  }
  if (min_width >= max_width) {
    stop("ars: `min_width` must be smaller than `max_width`.")
  }
  list(maxit = as.integer(maxit), tol = tol, max_width = max_width, min_width = min_width)
}

##' Validate the output file argument.
ars_validate_file <- function(file) {
  if (is.null(file)) return(NULL)
  if (!is.character(file) || length(file) != 1L || is.na(file) || !nzchar(file)) {
    stop("ars: `file` must be NULL or a single non-empty file name.")
  }
  file
}


## =============================================================================
## 2. Log density evaluation and log-concavity checking
## =============================================================================

##' Evaluate the log density, mapping -Inf to NA so that it can be detected.
ars_eval_logdensity <- function(f, x) {
  v <- tryCatch(f(x), error = function(e) {
    stop("ars: the density function failed when evaluated at ", paste(format(x), collapse = ", "),
         ": ", conditionMessage(e))
  })
  v <- .ars_safe_numeric(v, x)
  v[is.nan(v)] <- NA_real_
  v
}

##' Check log-concavity *locally* by verifying that the slopes of the tangent
##' segments are non-increasing, i.e. that the secant slopes between successive
##' evaluation points `s_i = (h(x_{i+1}) - h(x_i)) / (x_{i+1} - x_i)` satisfy
##' `s_i >= s_{i+1}` (second difference of `h` is <= 0).
##'
##' This is the discrete analogue of Gilks & Wild's assumption (i) (log density
##' concave) and (ii) (h' continuous).  It is the check that is applied
##' repeatedly *during sampling*, after each new point has been added to the
##' hull, so any observed non-log-concavity aborts the sampler with an error.
##'
##' @param x Numeric vector of evaluation points (must be sorted, length >= 3).
##' @param h Log density at `x`.
##' @param tol Numerical tolerance for the slope comparison.
##' @return NULL invisibly; errors if concavity is violated.
ars_is_log_concave <- function(x, h, tol = 1e-8, context = "log density") {
  x <- as.numeric(x)
  h <- as.numeric(h)
  if (length(x) < 3L) return(invisible(TRUE))
  if (anyNA(h) || any(!is.finite(h))) {
    stop("ars: the ", context, " must be finite at every evaluation point used to build the hull.")
  }
  slopes <- diff(h) / diff(x)
  bad <- which(diff(slopes) > tol * pmax(1, abs(slopes[-1L]) + abs(slopes[-length(slopes)])))
  if (length(bad)) {
    i <- bad[1L]
    stop("ars: the ", context, " is not log-concave: the slopes of the log density increase ",
         "between x = ", format(x[i]), " and x = ", format(x[i + 2L]),
         " (slopes ", format(signif(slopes[i], 6)), " then ",
         format(signif(slopes[i + 1L], 6)), "). ",
         "Adaptive rejection sampling requires a log-concave density.")
  }
  invisible(TRUE)
}


## =============================================================================
## 3. Hull construction and sampling
## =============================================================================

##' Build the initial adaptive-hull state from the starting abscissae.
##'
##' The state is an environment (used so that the hull can grow cheaply during
##' sampling) with components
##'   h       -- log density at `x`
##'   hprime  -- derivative of the log density at `x`
##'   lower, upper -- support bounds (possibly infinite)
##'   z       -- breakpoints (length n+1); z[1] = lower, z[n+2] = upper
ars_init_hull <- function(f, x, lower, upper) {
  h <- ars_eval_logdensity(f, x)
  hp <- ars_logdensity_derivative(f, x)
  ars_is_log_concave(x, h, context = "log density at the initial points")

  state <- new.env(parent = emptyenv())
  state$f <- f
  state$lower <- lower
  state$upper <- upper
  state$x <- as.numeric(x)
  state$h <- h
  state$hprime <- hp
  state$n_added <- 0L
  state$z <- ars_hull_breakpoints(state$lower, state$upper, state$x, state$h, state$hprime)
  ars_check_hull(state)
  state
}

##' Numerical derivative of the log density (central differences).
ars_logdensity_derivative <- function(f, x) {
  h <- 1e-5 * pmax(1, abs(x))
  fplus <- ars_eval_logdensity(f, x + h)
  fminus <- ars_eval_logdensity(f, x - h)
  d <- (fplus - fminus) / (2 * h)
  bad <- !is.finite(d)
  if (any(bad)) {
    stop("ars: could not compute the derivative of the log density at x = ",
         paste(format(x[bad]), collapse = ", "),
         ". Check that the density is strictly positive and well behaved at these points.")
  }
  d
}

##' Breakpoints of the tangent (upper-hull) piecewise linear approximation.
##'
##' Intersection of the tangents at x_i and x_{i+1}:
##'   z_{i+1} = (h(x_{i+1}) - x_{i+1} h'(x_{i+1}) - h(x_i) + x_i h'(x_i)) /
##'             (h'(x_i) - h'(x_{i+1}))
ars_hull_breakpoints <- function(lower, upper, x, h, hprime) {
  k <- length(x)
  mid <- numeric(k - 1L)
  if (k > 1L) {
    for (i in seq_len(k - 1L)) {
      denom <- hprime[i] - hprime[i + 1L]
      if (abs(denom) < 1e-12) {
        mid[i] <- (x[i] + x[i + 1L]) / 2
      } else {
        mid[i] <- (h[i + 1L] - x[i + 1L] * hprime[i + 1L] - h[i] + x[i] * hprime[i]) / denom
      }
    }
  }
  z <- c(lower, mid, upper)
  z
}

##' Verify that the hull is a valid upper bound: breakpoints strictly
##' increasing, every tangent non-negative at its own interval, and (at finite
##' support bounds) the tangents pointing outwards.
ars_check_hull <- function(state) {
  z <- state$z
  x <- state$x
  if (any(diff(z) < 0)) {
    stop("ars: the tangent hull is not ordered in x. This indicates that the log density is ",
         "not concave (the tangent intersections are not increasing).")
  }
  n <- length(x)
  for (i in seq_len(n)) {
    left <- z[i]
    right <- z[i + 1L]
    if (right <= left) {
      stop("ars: empty hull interval around x = ", format(x[i]),
           "; the log density appears not to be concave (tangents cross in the wrong order).")
    }
    if (is.finite(left)) {
      v <- state$h[i] + (left - x[i]) * state$hprime[i]
      if (!is.finite(v) || v < -1e-8) {
        stop("ars: the tangent at x = ", format(x[i]), " is not a valid upper bound on the left. ",
             "This indicates that the log density is not concave (or that `lower` is inside the support).")
      }
    }
    if (is.finite(right)) {
      v <- state$h[i] + (right - x[i]) * state$hprime[i]
      if (!is.finite(v) || v < -1e-8) {
        stop("ars: the tangent at x = ", format(x[i]), " is not a valid upper bound on the right. ",
             "This indicates that the log density is not concave (or that `upper` is inside the support).")
      }
    }
  }
  invisible(TRUE)
}

##' Log of the normalising constant of one piece of the upper hull, i.e.
##' log int_{left}^{right} exp(h(x_i) + (t - x_i) h'(x_i)) dt.
##' Works for infinite limits using the analytic limits of the integral.
ars_piece_log_integral <- function(left, right, xi, hi, hpi) {
  ## upper hull on the piece is  U(t) = hi + (t - xi) * hpi
  ## so  log U(t) = A + B t  with  A = hi - xi*hpi,  B = hpi
  A <- hi - xi * hpi
  B <- hpi
  if (abs(B) < 1e-14) {
    ## flat: integral = exp(A) * (right - left)
    if (!is.finite(left) || !is.finite(right)) {
      return(Inf)
    }
    return(A + log(right - left))
  }
  ## int_l^r exp(A + B t) dt = [exp(A + B t)/B]_l^r = exp(A)/B * (exp(B r) - exp(B l))
  ## Compute in a numerically stable way.
  hi_l <- if (is.finite(left)) A + B * left else -Inf
  hi_r <- if (is.finite(right)) A + B * right else -Inf
  if (B > 0) {
    ## B>0: term at r dominates (r could be +Inf)
    if (is.infinite(hi_r) || is.na(hi_r)) return(Inf)
    if (!is.finite(hi_r) && hi_r > 0) return(Inf)
    ## log( (exp(hi_r) - exp(hi_l))/B ) = hi_r - log(B) + log1p(-exp(hi_l - hi_r))
    if (hi_l > hi_r) {
      ## B > 0 but left dominates: fall back to the "left" branch
      return(ars_piece_log_integral_side(left, right, A, B))
    }
    return(hi_r - log(B) + log1p(-exp(hi_l - hi_r)))
  } else {
    ## B<0: term at l dominates
    if (!is.finite(hi_l)) return(Inf)
    ## log( (exp(hi_r) - exp(hi_l)) / B ) ; B<0 -> divide by -|B|
    ## = log( (exp(hi_l) - exp(hi_r)) / |B| )
    return(hi_l - log(-B) + log1p(-exp(hi_r - hi_l)))
  }
}

##' Fallback for the piecewise integral when the dominant endpoint is not the
##' one suggested by the sign of the slope (happens for degenerate pieces).
ars_piece_log_integral_side <- function(left, right, A, B) {
  hi_l <- if (is.finite(left)) A + B * left else -Inf
  hi_r <- if (is.finite(right)) A + B * right else -Inf
  m <- max(hi_l, hi_r)
  if (!is.finite(m)) return(Inf)
  tot <- exp(hi_l - m) + exp(hi_r - m)   # rough stable estimate
  m + log(tot) - log(abs(B))
}

##' Sample `m` values from the piecewise-exponential upper hull already
##' normalised, i.e. a vector of interval indices is returned.
ars_sample_hull_interval <- function(state, m) {
  n <- length(state$x)
  li <- vapply(seq_len(n), function(i) {
    ars_piece_log_integral(state$z[i], state$z[i + 1L], state$x[i], state$h[i], state$hprime[i])
  }, numeric(1L))
  if (any(is.na(li))) {
    stop("ars: the upper hull has non-integrable pieces; the density may not be log-concave ",
         "or its support may be wrong. Check `lower`/`upper`.")
  }
  maxli <- max(li)
  if (!is.finite(maxli)) {
    stop("ars: the normalising constant of the upper hull is infinite. ",
         "The log density is either not log-concave or growing on the supplied support.")
  }
  w <- exp(li - maxli)
  ## guard against all-zero weights
  if (sum(w) == 0 || !is.finite(sum(w))) {
    stop("ars: could not normalise the upper hull (numerical failure).")
  }
  prob <- w / sum(w)
  cum <- cumsum(prob)
  cum[n] <- 1
  u <- stats::runif(m)
  idx <- findInterval(u, cum) + 1L
  idx[idx > n] <- n
  idx
}

##' Draw `m` values from the piecewise exponential upper hull.
ars_sample_hull <- function(state, m) {
  n <- length(state$x)
  idx <- ars_sample_hull_interval(state, m)
  left <- state$z[idx]
  right <- state$z[idx + 1L]
  xi <- state$x[idx]
  hi <- state$h[idx]
  hpi <- state$hprime[idx]
  u <- stats::runif(m)
  out <- numeric(m)

  flat <- abs(hpi) < 1e-14
  ## flat pieces: uniform on the piece (must be finite)
  if (any(flat)) {
    lf <- left[flat]; rf <- right[flat]
    if (any(!is.finite(lf)) || any(!is.finite(rf))) {
      stop("ars: a flat piece of the log density has infinite support, which is not integrable.")
    }
    out[flat] <- lf + u[flat] * (rf - lf)
  }
  ## sloped pieces
  s <- which(!flat)
  if (length(s)) {
    l <- left[s]; r <- right[s]; sl <- hpi[s]; x0 <- xi[s]; h0 <- hi[s]
    ## inverse CDF on [l, r];  F(t) = (exp(s t) - exp(s l)) / (exp(s r) - exp(s l))
    log_p_l <- s * (l - x0)   # = h(l) - h(x0) ignoring base
    log_p_r <- s * (r - x0)
    ## handle infinite endpoints via the analytic inverse
    for (j in seq_along(s)) {
      ll <- log_p_l[j]; rr <- log_p_r[j]; uj <- u[s][j]; slj <- sl[j]
      if (!is.finite(ll) && !is.finite(rr)) {
        stop("ars: internal error: hull piece infinite at both ends.")
      }
      if (is.finite(ll) && is.finite(rr)) {
        ## standard case
        lo <- min(ll, rr); hi2 <- max(ll, rr)
        val <- log1p(uj * expm1(hi2 - lo)) + lo   # log( exp(lo) + u (exp(hi) - exp(lo)) )
        t <- x0[j] + val / slj
      } else if (!is.finite(ll)) {
        ## left = -Inf: exp(s(l - x0)) -> 0 if s*(l-x0) -> -Inf
        ## F(t) = exp(s(t-x0) - log_p_r )
        t <- x0[j] + (log(uj) + rr) / slj
      } else {
        ## right = +Inf: F(t) = 1 - exp(s(t - x0) - log_p_l)
        f <- 1 - exp(slj * (t <- x0[j]) - x0[j] * 0)
        ## use: 1 - u = exp(s(t-x0) - log_p_l)
        t <- x0[j] + (log1p(-uj) + ll) / slj
      }
      out[s][j] <- t
    }
  }
  if (any(!is.finite(out))) {
    stop("ars: generated a non-finite sample from the upper hull.")
  }
  ## keep samples strictly inside the support
  eps <- 1e-12 * pmax(1, abs(out))
  out <- pmin(pmax(out, if (is.finite(state$lower)) state$lower + eps else -Inf),
              if (is.finite(state$upper)) state$upper - eps else Inf)
  out
}

##' Add a new abscissa to the hull (mutates `state`).
ars_update_hull <- function(state, xnew) {
  if (any(!is.finite(xnew))) {
    stop("ars: cannot add a non-finite point to the hull.")
  }
  if (any(xnew <= state$lower) || any(xnew >= state$upper)) {
    stop("ars: cannot add a point outside the support ", "(", state$lower, ", ", state$upper, ").")
  }
  for (x in xnew) {
    if (any(abs(state$x - x) < 1e-12 * pmax(1, abs(x)))) next  # already present
    hnew <- ars_eval_logdensity(state$f, x)
    if (length(hnew) != 1L) hnew <- hnew[1L]
    if (is.na(hnew) || !is.finite(hnew)) {
      stop("ars: the log density is not finite at the new hull point x = ", format(x),
           ". The density must be strictly positive on its support.")
    }
    hpnew <- ars_logdensity_derivative(state$f, x)
    ## insert keeping x sorted
    pos <- findInterval(x, state$x) + 1L
    state$x <- append(state$x, x, after = pos - 1L)
    state$h <- append(state$h, hnew, after = pos - 1L)
    state$hprime <- append(state$hprime, hpnew, after = pos - 1L)
    state$n_added <- state$n_added + 1L
  }
  ## log-concavity check on the enlarged set (this is the check performed
  ## *during* sampling)
  ars_is_log_concave(state$x, state$h, context = "log density (after adding a hull point)")
  state$z <- ars_hull_breakpoints(state$lower, state$upper, state$x, state$h, state$hprime)
  ars_check_hull(state)
  invisible(state)
}

##' Log of the lower (squeezing) hull at `x`, given the current abscissae.
##' Outside [min(x), max(x)] the squeezing hull is -Inf (no squeeze available).
ars_squeeze_log <- function(state, x) {
  xs <- state$x
  res <- rep(-Inf, length(x))
  k <- length(xs)
  if (k < 2L) return(res)
  idx <- findInterval(x, xs)
  inside <- idx >= 1L & idx < k
  if (any(inside)) {
    i <- idx[inside]
    xi <- x[inside]
    sl <- (state$h[i + 1L] - state$h[i]) / (xs[i + 1L] - xs[i])
    res[inside] <- state$h[i] + (xi - xs[i]) * sl
  }
  res
}

##' Log of the upper (tangent) hull at `x`.
ars_upper_log <- function(state, x) {
  xs <- state$x
  idx <- findInterval(x, state$z)
  idx <- pmin(pmax(idx, 1L), length(xs))
  state$h[idx] + (x - xs[idx]) * state$hprime[idx]
}


